INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Circuit''s Edge', 'Circuit''s Edge is a computer game developed by Westwood Associates and released by Infocom in 1989. It is based on George Alec Effinger''s 1987 novel When Gravity Fails. The game is a hybrid interactive fiction/role-playing game; it contains a window of text, a graphic window for depiction of the player''s current location, and various menus and mini-windows for character statistics and other game functions.' FROM games WHERE igdb_id = 50150 ON CONFLICT (game_id, language_code) DO NOTHING;
