INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('vendetta', 91874, '1990-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co22ra.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc829u.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vendetta', 'The gameplay could be compared with the Last Ninja series. It has an isometric view and is flick screen. You can pick up useful items like weapons (knives, and guns), which blink when you enter a screen containing such an item, as well as the evidence needed to complete each stage. Any collected evidence is shown on a camera film reel. Once all the evidence is collected on a stage then the game changes to a driving game where you have to get to the next stage. The car is viewed from behind and you must avoid the other vehicles as well as helicopters dropping bombs but your car is armed with a cannon and missiles. Police cars have to be avoided or they will ask to see any evidence you have.' FROM games WHERE igdb_id = 91874 ON CONFLICT (game_id, language_code) DO NOTHING;
