INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The 4th Unit 5 - D-Again', 'D-Again is the fifth 4th Unit game. The criminal trade organization WWWF was finally defeated. The bionic soldier Blon-Win is appointed a high-ranked inspector and sent on a mission to protect the secret service agent Remi Binderk on the way to the United Nations conference in Geneva. On board the TGV train in France Blon-Win encounters her old acquaintance Dalzy, who tells her that former WWWF members have united to form the Einheit group, and are working on a new dangerous weapon known as G-R.' FROM games WHERE igdb_id = 66326 ON CONFLICT (game_id, language_code) DO NOTHING;
