INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('disk-jockey-boy', 46220, '1990-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/uqz3dnv42lm0zzgcfhuw.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disk Jockey Boy', 'Skating DJ Boy''s girl has been kidnapped by the town''s local goons and DJ Boy is the only one who can save the day. This coin-op conversion offers different rounds of side-scrolling beat-em-up gameplay, each with an end boss. DJ Boy is able to punch, kick, combine them in a flying attack and punch to both sides at the same time by pressing the main attack buttons. Although the visuals are less rough and friendlier than its contemporary counterparts, the difficulty is very unforgiving. DJ Boy has only four life bars and when they are gone, the game is over without continues. Defeated enemies leave behind coins. At the end of each stage the coins can be exchanged for a skateboard, a stronger punch or other items.' FROM games WHERE igdb_id = 46220 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 46220 AND p.igdb_id = 29 ON CONFLICT DO NOTHING;
