INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Barker Bill''s Trick Shooting', 'Barker Bill''s Trick Shooting was developed and published by Nintendo for the NES in 1990. It was loosely based on the cartoon show "Barker Bill''s Cartoon Show", popular in the 1950s. The game is essentially a shooting gallery taking place in a carnival, utilizing Nintendo''s Zapper gun. It was relatively successful, but was not regarded as a breakthrough game.' FROM games WHERE igdb_id = 9875 ON CONFLICT (game_id, language_code) DO NOTHING;
