INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Slick Shot', 'Slick Shot is a 1990 billiard arcade game developed and produced by Grand Products. Players choose one of two billiard games: Slickshot or 9 ball. Using a real cue stick and ball on a small pool table surface, a player must shoot the ball into the game cabinet to simulate the shot on the video screen. Infrared sensors on the table slate calculate the speed and direction the ball is traveling.' FROM games WHERE igdb_id = 337565 ON CONFLICT (game_id, language_code) DO NOTHING;
