INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Out Zone', 'Out Zone is a vertically scrolled run and gun video game set in the future of the year 2097, where an alien race from the fictional planet Owagira are threatening to wipe out humanity. After multiple failed attempts to defend Earth against their attacks, players assume the role of cyborg mercenaries recruited by the United Nations in a last-ditch effort to overthrow the invaders' FROM games WHERE igdb_id = 93519 ON CONFLICT (game_id, language_code) DO NOTHING;
