INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jumpjet', 'Jumpjet was an action side-scroller in which the player piloted a jet to complete four missions, culminating in a "final" boss fight against the "Head of Doom". Defeating all four levels would bring the player loop the player back to the first mission. Play would continue as such until the player ran out of lives.' FROM games WHERE igdb_id = 8334 ON CONFLICT (game_id, language_code) DO NOTHING;
