INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('guerriere-lyeward', 244995, '1990-01-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6dd0.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Guerrière Lyewärd', 'After World War III, humans have finally achieved world peace - or so they thought. Malevolent aliens have infected the human organism in a most treacherous way possible, turning young and pretty women into rampaging, violent nymphomaniacs. Only one person can stop the insanity - the attractive secret agent with the codename Lyewärd. Guerrière Lyewärd is a side-scrolling beat-em-up. The gameplay is very simple: the player moves the protagonist through strictly linear stages from left to right, each containing a few types of female enemies that attack the heroine from both sides. The secret agent can punch, kick, and jump. Power-ups such as health-restoring hearts and invincibility appear at set points during the stages, floating in the air. Each stage culminates with a boss battle against a powerful female enemy; defeating the boss leads to a lesbian sex scene.' FROM games WHERE igdb_id = 244995 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 244995 AND ge.slug = 'hack-and-slash-beat-em-up' ON CONFLICT DO NOTHING;
