INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('barney-bear-meets-santa-claus', 14286, '1990-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/nvhwcfunlzozygac8cvx.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Barney Bear Meets Santa Claus', 'Travel with Barney Bear to Santa''s toy factory! Barney Bear Meets Santa Claus is a colorful, musical, learning game for children ages 2-6. When Santa Claus comes down the chimney at Barney Bear''s house, he finds Barney Bear still awake! So Santa asks Barney Bear to ride in his sleigh to his toy factory at the North Pole. This short interactive story takes Barney Bear to the toy factory, where he sees elves, plays games and gets to make toys. Barney Bear Meets Santa Claus includes a spelling game, a mix-up-the-parts toy machine, a find-the-elf game, a missing letter game, and a coloring book program with many pictures to color. This is a game full or surprises and discovery that allows ever very young children to play without any adult supervision.' FROM games WHERE igdb_id = 14286 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 14286 AND ge.slug = 'adventure' ON CONFLICT DO NOTHING;
