INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ziriax', 'Ziriax is a horizontal scrolling shoot ''em up developed by The Whiz Kids and published by The Software Business. It was released in 1990 for the Amiga.' FROM games WHERE igdb_id = 80305 ON CONFLICT (game_id, language_code) DO NOTHING;
