INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('impossamole', 12611, '1990-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co43iu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ark9l.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Impossamole', 'For Monty Mole, a day at the beach turns into the adventure of his life when he''s beamed aboard an alien spacecraft. He''s transformed into Impossamole, with super powers to save their planet from the evil Vlarg! Now you''re up to your cape in Vlarg''s monster bosses with crack-up creatures ready to nail your tail! Power up your laser to blast the Dragon Boss. Bomb the Abominable Snowman. Then trash the Venus Moletrap before he has you for lunch. Swim, fly and blast through five wacky action-packed worlds. The fiendish Vlarg awaits your final desperate battle!' FROM games WHERE igdb_id = 12611 ON CONFLICT (game_id, language_code) DO NOTHING;
