INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tantei Jinguji Saburo: Toki no Sugiyuku Mama ni', 'Tantei Jinguuji Saburou: Toki no Sugiyuku Mama ni is an Adventure game, published by Data East, which was released in Japan in 1990. The 4th installment of the Tantei Jinguuji Saburo (Jake Hunter) series where Jinguji investigates a simple burglary while Yoko searches for a young boy''s home.' FROM games WHERE igdb_id = 48883 ON CONFLICT (game_id, language_code) DO NOTHING;
