INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Ball Z: Kyoushuu! Saiya-jin', 'Dragon Ball Z: Kyoushuu! Saiya-jin is a role playing video game and the first Dragon Ball Z console game. It was released only in Japan by Bandai on October 27, 1990, for the Nintendo Famicom. There was a limited edition gold cartridge of the game released. Kyoushuu! Saiyan is also one of the games included in the game compilation J Legend Retsuden for Nintendo 3DS.' FROM games WHERE igdb_id = 78229 ON CONFLICT (game_id, language_code) DO NOTHING;
