INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('stryx', 12784, '1990-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4o6a.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stryx', 'You''re really up against it this time. Those revolting robots have finally upped and turned their horribly powerful weapons on their kind human masters. Someone''s got to stop them before it all gets out of hand. I mean, you just can''t have bloodthirsty Cyborg assassins roaming the streets of Dome City and expect the citizens to put up with it. Who on Earth is going to sort out the mess? You guessed- you get the job. Fortunately, you are just a little bit on the special side. You are Stryx, the product of Project Alpha Secure, the meanest fighting, smartest thinking machine ever invented. Half-man, half-robot, you are the business, the only one who can stop those wicked Cyborgs. You''ll have to work hard, though, blasting hordes of the revolting creatures (such a sad waste of scrap metal) and rescuing the keys to the Lifeforce. So, Stryx, you''d better get your jet pack on for some high level robot stomping through the immensely complex underground world of the Dome cities. It''s a tough assignment, and time is running out.' FROM games WHERE igdb_id = 12784 ON CONFLICT (game_id, language_code) DO NOTHING;
