INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-official-everton-fc-intelligensia', 314965, '1990-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8u1i.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sctybr.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Official Everton FC Intelligensia', 'The Official Everton F.C. Intelligensia is a quiz game about football. Despite the title it''s not specifically about Everton as the player can choose to represent any English top flight team of the 1989/90 season and it features question about both domestic and international football. All questions have three alternatives to choose from and has to be done before time runs out. Some are accompanied with a picture. The game is built around the FA Cup and like in real life first division clubs enters the competition in the third round. In each round the player has to answer a number of questions which depends on the opposition drawn and if it''s a home or away game. Opposition from higher divisions lead to more questions being asked. Goals are scored by answering questions correctly and the number of answers required depend on the difficulty level chosen. In the same way goals are conceded by answering questions wrongly.' FROM games WHERE igdb_id = 314965 ON CONFLICT (game_id, language_code) DO NOTHING;
