INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World Class Soccer', 'Italy 1990 (also known as World Class Soccer in the United States and Italia 1990 in most of Europe) is a soccer video game published by U.S. Gold and programmed by Tiertex Design Studios in 1990. It features the 1990 FIFA World Cup held in Italy but is not part of the official FIFA World Cup series. For the American market it was branded as World Class Soccer. In Europe (except the U.K.) it was released as Italia 1990 by U.S. Gold in association with Erbe Software. It was released for Amiga, Amstrad CPC, Atari ST, Commodore 64, ZX Spectrum and DOS.' FROM games WHERE igdb_id = 40864 ON CONFLICT (game_id, language_code) DO NOTHING;
