INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('motorodeo', 40787, '1990-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/o5es90j2zd6gzqolnunm.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MotoRodeo', 'You''re second in the grueling competition of an all-day MotoRodeo. Your customized truck, a cherry little number, speeds through the dangerous obstacle course. You quickly break through a brick wall, rumble through a muddy ditch, and jump high into the air. You grin widely as you land on a Plymouth, crushing it beneath the weight of your monster truck.  Up till now, you and your opponent, Trucker Tom, have been neck and neck throughout the competition, but you''ve just pulled ahead. Your truck paid its dues during the early part of the competition, but you''re confident that you''ve got the skills needed to outmaneuver Tom as you race for the finish line.  Your adrenalin pounds. You psych yourself up for the few remaining obstacles. You''re only slightly ahead of Tom, but there are still a few more walls and cars to crush. Good thing you learned quickly to jump the mud which is slowing Tom down.  You rev your engine, add a burst of acceleration, and jump the last mud hole as you race for the finish line. Trucker Tom has finally met his match!' FROM games WHERE igdb_id = 40787 ON CONFLICT (game_id, language_code) DO NOTHING;
