INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Shark', 'The player controls a small space ship which can move in all directions on a field that horizontally scrolls left and right. The player can shoot horizontally. Each level has a set number of alien vessels that must be destroyed to progress to the next level. Vessels track invariably towards the player, and the player loses a life if hit. The player starts with 6 vessels, and it''s game over when all are lost.' FROM games WHERE igdb_id = 181539 ON CONFLICT (game_id, language_code) DO NOTHING;
