INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kattobi-takuhai-kun', 37682, '1990-11-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6xhs.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kattobi! Takuhai Kun', 'A top-down driving game where the player must deliver various packages around town, upgrading their moped as they complete jobs. The game has a subversive sense of humour. Kattobi! Takuhai-kun ("Fury! Delivery Boy") is a top-down action/driving game from Advance Communications Company and Tonkin House. The player is a delivery boy who must make a series of increasingly surreal deliveries across town, occasionally leaving the country and getting into trouble with drug trafficking. As the player complete jobs, they can use their earnings to buy better two-wheeled delivery vehicles, upgrading from a pedal bike to a moped to a state-of-the-art motorcycle. Destroying their vehicle (by losing a life) drops them back down to the regular pedal bike. The game was released exclusively in Japan on the PC Engine. It is perhaps best known to western audiences for its appearance on an episode of the Japanese video game TV show GameCenter CX.' FROM games WHERE igdb_id = 37682 ON CONFLICT (game_id, language_code) DO NOTHING;
