INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lost Patrol', 'Lost Patrol is a survival action role-playing game with strategy elements. "We’re fit, we’re alive, but we’re not back home." In this classic multi-genre DOS game, take command of the seven survivors of a U.S. helicopter crash in Vietnam, desperately trekking across 57 miles of harsh terrain infested with booby traps and enemy soldiers.' FROM games WHERE igdb_id = 37270 ON CONFLICT (game_id, language_code) DO NOTHING;
