INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Minasan no Okage-sama Desu!', 'The second Japanese mahjong game to run on Neo Geo hardware is based on a bizarre and comedic Japanese variety show. In between mahjong matches, the player rolls dice and moves along a board game track; landing on different squares provides special effects, and decides which opponents the player will face.' FROM games WHERE igdb_id = 64013 ON CONFLICT (game_id, language_code) DO NOTHING;
