INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Emlyn Hughes Arcade Quiz', 'Computer quiz game. The players travel around a zig-zagging pathway, answering questions as they go. There are coins to pick up and fruit to collect, and special square like ‘kicker’ which send you flying off in the wrong direction or ‘blockers’ which get in your way. Every few seconds the path moves to the left, taking you further from the ‘Win bar and closer to the ‘Lose’ bar, so every second counts if you want to win.' FROM games WHERE igdb_id = 13636 ON CONFLICT (game_id, language_code) DO NOTHING;
