INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simulcra', 'Simulcra is a 1990 computer game for the Amiga and Atari ST developed by Graftgold published by MicroStyle. A 3D polygonal third-person shooter, the player controls an attack craft which can switch between ground-based and aerial attack modes, traversing a wireframe virtual environment.' FROM games WHERE igdb_id = 15367 ON CONFLICT (game_id, language_code) DO NOTHING;
