INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Ultimate Stuntman', 'Too hot to handle? Or can you take up the challenge? Equipped with a dazzling range of weapons and skills, travel through scores of different action scenes, battling against the hottest, meanest, mechanized maniacs ever dreamed up! Rescue the kidnapped scientist to halt the corrupt plans of Dr. Evil. Heaps of hardware, power-ups, bonuses, booby-trapped bombs and the baddest bosses!' FROM games WHERE igdb_id = 48264 ON CONFLICT (game_id, language_code) DO NOTHING;
