INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('deep-dungeon-iv-kuro-no-youjutsushi', 48513, '1990-04-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7k9i.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deep Dungeon IV: Kuro no Youjutsushi', 'Deep Dungeon IV: Kuro no Youjutsushi is the fourth and final installment in the Deep Dungeon series. Unfortunately this game has removed the custom character feature of the previous game. Through the game, the player will meet up to two additional playable characters with predetermined class. This game also reverts to the standard practice or randomizing characters'' stat growth when gaining an experience level. New to this engine is that the player can eventually learn to summon two monsters to function as a temporary additional party member for a single battle. It also removed the feature that stops random battles when the player is significantly more powerful than the enemies. This isn''t as bad as it seems as the maps in this game are also much smaller (whereas the previous games used multi-floor dungeons up to 32x32 tiles, the dungeons in this game are either single floor, or multiple floors that can fit within a single 32x32 map) In this game, the player can accept "requests" from the non-player characters. These are optional tasks that will reward the player with bonus items, experience or money when finished.' FROM games WHERE igdb_id = 48513 ON CONFLICT (game_id, language_code) DO NOTHING;
