INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Architect', 'Architect is an unlicensed software utility released, apparently, for or with the Dr. PC Jr. (a Chinese Famicom clone system). The game plays like a drawing tool using pre-created bits of architecture. The building most commonly shown is a Chinese or Japanese-like pagoda or temple.' FROM games WHERE igdb_id = 326623 ON CONFLICT (game_id, language_code) DO NOTHING;
