INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Talking Ghostbusters II', 'The Talking Ghostbusters II/Ghostbusters II is a handheld game (referred in boxed releases as a Electronic LCD Game) that was was released by Micro Games of America (also going by Micro Games USA briefly) in 1990. The game has variant releases, though it appears that the actual game and device layout don''t change in any variants.' FROM games WHERE igdb_id = 218434 ON CONFLICT (game_id, language_code) DO NOTHING;
