INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Flood', 'Flood is a side-scrolling platformer in which the player takes control of Quiffy, a strange amphibious creature, on his quest to stop the flooding of his underground world. The gameplay is familiar (it is a platformer afterall), but there are some novel ideas, such as Quiffy''s ability to cling to walls and ceilings.' FROM games WHERE igdb_id = 12104 ON CONFLICT (game_id, language_code) DO NOTHING;
