INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yami no Ketsuzoku', 'The sixth installment in System Sacom''s Novel Ware series, Yami no Ketsuzoku is a Japanese-style adventure game. The player interacts with the environment by selecting objects to look at, conversation topics, and locations to travel to from a menu. There are no puzzles or inventory items to use. The game features extended text descriptions, cutscenes, and dialogues which sometimes prompt the player to make choices for the heroine.' FROM games WHERE igdb_id = 112035 ON CONFLICT (game_id, language_code) DO NOTHING;
