INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Storybook Weaver', '"Storybook Weaver" is a 1990 educational program for the Apple IIGS developed by Charolyn Kapplinger, Patricia Korn, John J. Krenz, Brian S. Nesse, Jean Sharp, and Steve Zehm, and distributed by MECC. The program allowed children to create their own stories using provided images, sound effects, and music. It was later released in 1992 for DOS with some graphical upgrades, and for Windows in 1995 as "Storybook Weaver: Classic Edition". It was followed by an enhanced version, called Storybook Weaver Deluxe, released in 1994.' FROM games WHERE igdb_id = 252083 ON CONFLICT (game_id, language_code) DO NOTHING;
