INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Designasaurus II', 'Designasaurus II lets players design a dinosaur and travel back to the Mesozoic era (Triassic, Jurassic and Cretaceous periods) in search of stolen Gigantodon DNA. Players must fight for their lives and forage for food to survive.' FROM games WHERE igdb_id = 73899 ON CONFLICT (game_id, language_code) DO NOTHING;
