INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kyuukai-douchuuki', 45724, '1990-05-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2yvo.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kyuukai Douchuuki', 'Kyuukai Douchuuki is a 1990 arcade baseball game by Namco which they ported to the Sega Mega Drive in 1991. Neither version left Japan. The game is a generic baseball game where you are only in control of the pitcher and batter; once the batter hits the ball, you can only watch what your team does. When batting, the D-pad moves around and C swings. When pitching, Left and Right move around and some amount of time holding the C button appears to pitch. It is a spin-off of Shadowland (Youkai Douchuki).' FROM games WHERE igdb_id = 45724 ON CONFLICT (game_id, language_code) DO NOTHING;
