INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ninja Combat', 'Ninja Combat is a 1990 side-scrolling beat ''em up video game developed by Alpha Denshi and published by SNK. It was one of the launch titles for both the Neo Geo MVS (arcade) and AES (home) systems. It is notorious for its unbalanced difficulty and odd design and gameplay ideas.' FROM games WHERE igdb_id = 39889 ON CONFLICT (game_id, language_code) DO NOTHING;
