INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Soviet', 'Soviet is an top-down arcade game in which our only occupation will be to shoot everything that moves across two phases in which you have to collect a certain number of hostages, that we have to rescue by simply approaching them. . To protect our tank we can use the three types of weapons available to us, a long-range shot, a short-range shot and a limited number of super-bombs that destroy all the enemies that are around.' FROM games WHERE igdb_id = 93441 ON CONFLICT (game_id, language_code) DO NOTHING;
