INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Madou Monogatari 1-2-3', 'Madou Monogatari 1-2-3 consists of three separate adventures, all of which star young magician Arle Nadja. Billed as a "Magical Voice Role Playing Game", Madou Monogatari 1-2-3 combines diverse, colorful monster design with a then-unusual amount of voice work. The game is also notable for a near-complete lack of numerical stats, instead portraying health, damage, and magic capacity using text cues and Arle''s face portrait.' FROM games WHERE igdb_id = 94394 ON CONFLICT (game_id, language_code) DO NOTHING;
