INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('formation-soccer-human-cup-90', 42046, '1990-04-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6xez.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Formation Soccer: Human Cup ''90', 'A Japan-only soccer game developed by Human for the 1990 World Cup in Italy. It was the first in the Formation Soccer series. Formation Soccer: Human Cup ''90 is a soccer game for the PC Engine that was released in Japan exclusively. It is the first of the Formation Soccer games from Human Entertainment: many of which would end up on the Super Famicom/Nintendo as "Super Formation Soccer", in a similar pattern as Human''s Fire Pro Wrestling series which also became Super Fire Pro Wrestling once they started coming out on the Super Famicom. Formation Soccer uses a vertical-scrolling view of the pitch. The game was designed and released to coincide with the 1990 World Cup event set in Italy. It features sixteen teams, though only eleven of those actually qualified for the World Cup. The player can choose between a single game Exhibition mode and a tournament "Human Cup" mode to choose between. Teams The following sixteen teams could be selected for use in either mode: Italy (the hosts) Brazil The Netherlands U.S.S.R. Argentina West Germany Denmark (Denmark did not actually qualify for the 1990 World Cup) England Spain France (France did not actually qualify for the 1990 World Cup) Uruguay Poland (Poland did not actually qualify for the 1990 World Cup) Yugoslavia USA Mexico (Mexico was disqualified during the qualification process) Japan (Japan did not actually qualify for the 1990 World Cup)' FROM games WHERE igdb_id = 42046 ON CONFLICT (game_id, language_code) DO NOTHING;
