INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Misty Blue', 'A mystery adventure game by Enix from 1990. Players control a musician named Kazuya Mizukami, who returns to Japan and, following the death of a music producer, becomes a prime murder suspect. To clear his name, he will need the help of friends in the music and modelling industries.' FROM games WHERE igdb_id = 64387 ON CONFLICT (game_id, language_code) DO NOTHING;
