INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Football Champ', 'An arcade football/soccer game. The game scrolls horizontally at a slight angle, and recreates the coin-op''s close-up zoom effect after a player scores. Only a small area of the pitch is on screen at a time, but there is a scanner to show the whole pitch. Although the game has a referee, he often loses attention, and these moments give you a chance to foul, punch or side-swipe opposition players. One and two player options are included.' FROM games WHERE igdb_id = 39481 ON CONFLICT (game_id, language_code) DO NOTHING;
