INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Popeye', 'Popeye is a Japan-exclusive Game Boy video game based on the comic strip of the same name licensed from King Features Syndicate. A cancelled US version was found in the 2020 Nintendo data leak, intended to be published by INTV Corporation. The scenario is a maze and the player controls Popeye who has a time limit to collect some hearts, find Olive Oyl and save Swee''Pea which only appears somewhere to be saved after the hearts were collected and Olive found.' FROM games WHERE igdb_id = 283579 ON CONFLICT (game_id, language_code) DO NOTHING;
