INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pharaoh''s Tomb', 'Pharaoh''s Tomb is an arcade-adventure game set in a huge Egyptian pyramid. Explore 20 uniquely-dangerous levels riddled with ingenious puzzles and traps. You start with five lives and a few spears, which can he thrown at offending denizens that patrol the pyramid. Pharaoh''s Tomb consists of four unique volumes, which concludes with "Nevada''s Revenge."' FROM games WHERE igdb_id = 35505 ON CONFLICT (game_id, language_code) DO NOTHING;
