INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kagerou Labyrinth', 'An old explorer finds the ruins of an old civilization. in them, a few workers claim to have been trapped in "a different world with strange powers". the old explorer asks a scientist among his friends and his daughter to go investigate. they enter and are transported by a blinding light into a strange labyrinth.' FROM games WHERE igdb_id = 338819 ON CONFLICT (game_id, language_code) DO NOTHING;
