INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'STED: Iseki Wakusei no Yabou', 'STED: Iseki Wakusei no Yabou ("STED: Starfield of Memorable Relics") is a science-fiction roleplaying game developed for the Nintendo Entertainment System by Alpha Denshi and published by K. Amusement Leasing on July 27th, 1990 in Japan. The game takes place during "Star date 0991" and has the player take control of a group of heroes as they track down a distress signal sent from a distant planet just as a significant rise in "monster activity" has been detected.' FROM games WHERE igdb_id = 48703 ON CONFLICT (game_id, language_code) DO NOTHING;
