INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Atomino', 'Against the clock, you use your chemical tendencies to build molecules out of atoms provided. And don''t be surprised if the very atom you don''t need will be the one you''re given to use next... Pray for a Joker Atom! If you don''t look like a mad scientist now, you will by the time you''ve tackled Atomino! Up and atom!' FROM games WHERE igdb_id = 11922 ON CONFLICT (game_id, language_code) DO NOTHING;
