INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Batman', 'Batman is a horizontally scrolling beat ''em up arcade game released by Atari Games, Midway Games, Data East and Namco in 1990 in North America, 1991 in Japan and 1991 in Europe. The storyline is based on the eponymous 1989 movie. It features stages based on locations in the film, including first-person control of the Batmobile and the Batwing. The game features audio clips of Batman (Michael Keaton) and the Joker (Jack Nicholson) as well as digitized photos from the movie. Batman can use various weapons, such as batarangs and gas grenades, as he takes on various goons and the Joker.' FROM games WHERE igdb_id = 164313 ON CONFLICT (game_id, language_code) DO NOTHING;
