INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nekojara Monogatari', 'This game is a dungeon crawling RPG. In it, you control a boy who woke up one day to find himself transformed into a cat. He learns that the royal heirloom of Cat Land has been stolen. He reluctantly goes on an adventure to retrieve it, as it is the only way to turn back.' FROM games WHERE igdb_id = 213302 ON CONFLICT (game_id, language_code) DO NOTHING;
