INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bad-blood', 11335, '1990-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5wre.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bad Blood', 'A nuclear war has turned the world into a wasteland. The pure-blooded humans have retreated in large cities while mutants live in small villages on the plains where they make a living by hunting the many monsters. Now one of the human leaders, Lord Dominix, wants to start a war to wipe out all the "bad-blooded" mutants. Your village chief has assigned you with the task of preventing this war. Bad Blood is a top-down action game with light role-playing elements. You can not create your own character but have to pick one of the three predefined ones: Varrigg (a strong green mutant who fights with his bare hands), Dekker (a human male armed with a knife) or Jakka (she looks human but can shoot laser beams from her eyes like Cyclops of X-Men fame). The choice you make has only a limited impact on gameplay and storyline. Gameplay consists of exploring the world map, visiting several cities and villages, talking with NPCs, picking up items and new weapons (like shotguns, grenades, Uzis etc.) and lots of real-time combat. Bad Blood lacks character stats and character development. The game has a day-night cycle which influences the amount of monsters on the plains and whether or not you can talk with some NPCs.' FROM games WHERE igdb_id = 11335 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 11335 AND ge.slug = 'role-playing-rpg' ON CONFLICT DO NOTHING;
