INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('full-throttle-2', 327805, '1990-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co99g5.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Full Throttle 2', 'FULL THROTTLE 2 is an arcade racing game published by Zeppelin Games Ltd in 1990. It is available in English and Russian. The game, developed by Michael Batty, offers an exciting superbike driving experience with incredible scaling speeds, detailed landscapes, and a unique gravity variation system. Get ready for the ultimate thrill since the original FULL THROTTLE, competing against forty of the world''s best riders on eight full-scale international circuits. The game can be played on the ZX Spectrum 48K and ZX Spectrum 128 +3 with various joystick interfaces.' FROM games WHERE igdb_id = 327805 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 327805 AND c.slug = 'zeppelin-games' ON CONFLICT DO NOTHING;
