INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bomberman-users-battle', 42055, '1990-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6xct.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bomberman: Users Battle', 'This multiplayer-only Bomberman release is exceedingly rare and seems to have been produced for demo kiosks, tournaments, or both. Users Battle is a Bomberman game for the PC Engine, released only in Japan. It bears a 1990 copyright, just like the original release of Bomberman for the platform. Additionally, it plays the same title screen music upon boot, but it has a different title screen, only allowing for multiplayer play for two to five players. It lacks the skull mode option of the full Bomberman release, but otherwise shows similar menus and styles to Bomberman''s multiplayer mode. It is believed that Users Battle was created in extremely limited quantities for use at tournaments, demo kiosks, or both. Some online sources estimate the number of cards produced at around 1,000.' FROM games WHERE igdb_id = 42055 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 42055 AND p.igdb_id = 86 ON CONFLICT DO NOTHING;
INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('panic-space', 41371, '1990-10-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/gjo6bcawnvb5ftv8sldk.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Panic Space', 'The second game to be released as a coverdisk special for the Japanese Famimaga magazine. Panic Space is a game based around the laser deflection puzzles that are common in games in the Zelda series as well as others.  Panic Space, or Famimaga Disk Vol. 2 Panic Space, is a puzzle game in which the goal is to reflect a laser to an exit panel in order to open the way to the next stage. The laser cannot hit any of the stage''s surrounding wall: were it do so, it would cause the level to explode and the player to lose a life (from an initial allotment of five, though this can be increased while playing the game). Much of the time the various reflectors (which send the beam off at a 90 degree angle) and blocks (which simply stop the laser in its tracks) must be maneuvered into place before the laser should be tested on them.  The robotic protagonist also has access to three different power-ups. These appear on every level and quickly cycles through the three types - the player must grab it when it stops on the desired power-up. These include a stopwatch that extends the time the player has to complete the stage, a bomb can that can eliminate one block and is occasionally necessary to beat stages and a galaxy spiral that can be placed anywhere to temporarily stop the laser.' FROM games WHERE igdb_id = 41371 ON CONFLICT (game_id, language_code) DO NOTHING;
