INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Parodius da!: Shinwa kara Owarai he', 'A shoot''em up arcade game and the second title in the Parodius series. Similar to the first game the player has a choice of characters to play as: Tako the Octopus (aka Mr. Parodius), Pentarou (son of the penguin from Antarctic Adventure), Twin Bee (main character of TwinBee) and the Vic Viper spaceship from Gradius. However in this game they each have unique weapons and upgrades. The game has ten stages and like the first game it features a mix of characters and enemies from different Konami series as well as absurd fantasy elements.' FROM games WHERE igdb_id = 37307 ON CONFLICT (game_id, language_code) DO NOTHING;
