INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vasteel', '"Two Powerful Brothers. Two Powerful Armies. One Survivor." Vasteel is a hex-based war strategy game in its core. The story mode takes the player (who controls either Stefan''s or Faliall''s armies) through various top-down maps, on which the two armies will try to annihilate each other, advance to a better position, conquer enemy cities, etc.' FROM games WHERE igdb_id = 92701 ON CONFLICT (game_id, language_code) DO NOTHING;
