INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Awesome', 'Awesome is a science fiction action video game released by Psygnosis for the Amiga and Atari ST in 1990. It features a variety of gameplay styles, from overhead shooting to Asteroids-esque sequences, and a pre-rendered ray-traced intro sequence. The antagonist of the game is John Winner. Scenes and music from the game were featured in Psygnosis''s later game Lemmings as in-jokes, in a Taxing rated level called "What an AWESOME level". The theme music for Awesome was composed by Tim Wright. The box art for Awesome was painted by science fiction artist John Harris.' FROM games WHERE igdb_id = 5877 ON CONFLICT (game_id, language_code) DO NOTHING;
