INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'James Bond 007: The Spy Who Loved Me', 'James Bond 007: The Spy Who Loved Me is a video game adaptation of the 1977 James Bond film The Spy Who Loved Me. The game was released for the Amiga, Atari ST, Amstrad CPC, Commodore 64, DOS computers, Sega Master System and ZX Spectrum in 1990. A version was planned for PS1 but was cancelled. The Spy Who Loved Me is a top-down shooter game in which the player navigates James Bond driving a modified Lotus Espirit. It features the characters from the film and some new characters.' FROM games WHERE igdb_id = 44098 ON CONFLICT (game_id, language_code) DO NOTHING;
