INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-light-corridor', 12438, '1990-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6jbk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/fsfzo4los89yhza9okov.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Light Corridor', 'The player uses a paddle to hit a metal ball down a long corridor. The player releases the ball (which is stuck to the paddle at the beginning of the game) and it will travel down the corridor until it hits a wall or similar obstacle and bounces back towards the player. At this point, the player will need to hit the ball again. If he does not, the ball will hit him and he will lose a life. The game will continue from where the player stopped, and the ball will once again be attached to the paddle. When the ball is travelling down the corridor, the player must walk and follow it. The object of the game is to reach the end of the corridor. Obstacles such as moving elevator-style doors make navigating the corridor difficult and success relies on the player''s quick reactions and forward planning. Collectable power-ups make progress easier. The colour of the corridor changes after every four levels, and there are fifty levels in total.' FROM games WHERE igdb_id = 12438 ON CONFLICT (game_id, language_code) DO NOTHING;
