INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hanii-on-the-road', 42068, '1990-09-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6fgv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scm9z2.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hanii on the Road', 'Hanii on the Road (aka Hany on the Road or Honey on the Road) is a side scrolling action game by Face. After Hanii''s exploits in Hanii in the Sky, the little Haniwa clay doll is back on a new mission. This time around, our cute friend must free the world from all the demons and other evil creatures that escaped from the Gods'' realm. But this time around he''s not flying or shooting balls of energy - instead, he must run along a roadway divided into four lanes, each moving at different speeds. And things are just not as easy as it may sound - Hanii has to jump over various enemies and try not to fall into deep holes dug into the ground, without forgetting the occasional change in scrolling direction and the myriad of other exciting, and often lethal, effects. A time limit also urges him to hurry and to quickly reach the end of each stage. Every little helps, and tiny wood signs scattered around every road tell Hany how far the next exit is. Additionally, special items can be collected along the way, such as Blue jars giving Hanii extra lives (twenty five of them need to be collected though), Mystery Jars giving from 100 to 1000 points, Extra Lives, Time Clocks, Rockets, Trampolines and other unique and often bizarre super powers (he can turn into a race-car or an almighty warrior in some stages!). Hanii on the Road consists of many levels and features a non-linear structure with interconnected paths to follow, as well as bosses. The game also offers a two simultaneous player mode where Lemon, a yellow version of Hanii, comes to the rescue.' FROM games WHERE igdb_id = 42068 ON CONFLICT (game_id, language_code) DO NOTHING;
