INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'American Horseshoes', 'Each player can choose from one of four characters: Lucky Lou, Diamond Dave, Tossin'' Tom and Mayhem Mary. There are two pitches in each inning. Players may select grip and throwing angle prior to each pitch. The rolling of the trackball determines the distance of each pitch. After each inning the scoring with shown with an overhead shot of the stake area. Each player''s score is shown throughout the game at the top of the screen. Up to nine innings can be played per game.' FROM games WHERE igdb_id = 39376 ON CONFLICT (game_id, language_code) DO NOTHING;
