INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Back to the Future Part II & III', 'Back to the Future Part II & III is the sequel to the original Back to the Future game, and is based loosely off of the second and third films of the popular Back to the Future movie franchise. The game was developed by Beam Software for the Nintendo Entertainment System. The game was received fairly negatively when released-with many complaining in particular about the game''s length coupled with lack of a save feature.' FROM games WHERE igdb_id = 8517 ON CONFLICT (game_id, language_code) DO NOTHING;
