INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('links-the-challenge-of-golf', 12666, '1990-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa4nk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/aryc8.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Links: The Challenge of Golf', 'Links redefined what golf on the PC should look and play like; it migrated golf from a sports game to a simulation. Good use of VGA''s 256 colors made for a realistic course with trees, water, sandtraps, and the fairway. The addition of ball physics, mulligans, changing the lie of the ball, real digitized environmental sounds (even through the PC speaker), and the ability to view a replay (even from multiple angles) gave PC golf games a new echelon of quality to match.' FROM games WHERE igdb_id = 12666 ON CONFLICT (game_id, language_code) DO NOTHING;
