INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('conquests-of-camelot-the-search-for-the-grail', 7566, '1990-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5v59.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar21om.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Conquests of Camelot: The Search for the Grail', 'With Conquest of Camelot, designer Christy Marx has dug deep into the most ancient roots of legend to restore the power and passion of King Arthur and his court: his queen''s forbidden love for Sir Lancelot; the struggle for supremacy between Christianity and the ancient Roman warrior-god, Mithra. The blending of myth, history and religion behind the Grail legend is dealt with honestly and directly. This combination of pre-Medieval history and ancient legend makes for a more sophisticated, complex and powerful view of Arthur than any you may have seen before. Conquests of Camelot designer Christy Marx is best known for writing the "Jem" animated TV series, and the "Sisterhood of Steel" comics and graphic novel. With her husband and professional partner, illustrator Peter Ledger, she has researched Arthurian myths and legends extensively for many years in preparation for writing this game.' FROM games WHERE igdb_id = 7566 ON CONFLICT (game_id, language_code) DO NOTHING;
