INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yolanda: The Ultimate Challenge', 'A notoriously difficult platformer for Amiga and Atari ST, where you take the part of Yolanda, offspring of the mighty Hercules himself, cursed by Hera. There are twelve tasks to complete and a trainer level, over fifty levels randomly selected. The player may have to play up to five screens to complete a task. The twelth task can only be played if you have completed the first eleven tasks.' FROM games WHERE igdb_id = 78390 ON CONFLICT (game_id, language_code) DO NOTHING;
