INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battle Royale', 'It''s wrestling mayhem out of control! Five maniacs hit the mat in a no-holds-barred, free-for-all brawl with no rules, no refs and absolutely no mercy! Team up with friends to nail opponents. Now look out! They''re coming after you! Smash ''em, bash ''em and throw ''em over the ropes! The sound is so intense you''ll feel every crushing hit, every cracking bone. It''s furious, non-stop action for up to five players ... a winner-take-all gang fight for survival!' FROM games WHERE igdb_id = 8938 ON CONFLICT (game_id, language_code) DO NOTHING;
