INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Star Soldier', 'Move fast and blast! It''s a nonstop explosion of fire power and you''re streaking through space, right in the middle of it! The Brains Cult you once defeated is back, badder than ever. But your finger''s on the trigger of an incredible new techno-attack! Scorch the Scorpion with a nuclear a sting. Fire your heat-seeking sidewinders. Then power-up to launch your doomsday Super Bomb! Blow those Brains out and save the galaxy. Then challenge your friends with a special competition time mode to prove who the Super Star really is!' FROM games WHERE igdb_id = 44339 ON CONFLICT (game_id, language_code) DO NOTHING;
