INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nekketsu High School Dodgeball Club: Soccer Story', 'Nekketsu High School Dodgeball Club: Soccer Story is the original Japanese version of the game released in other regions under the title of Nintendo World Cup. The Japanese version is part of the Kunio-kun/Nekketsu High series. The game was originally released under the title of Nekketsu Koukou Dodgeball Bu: Soccer-hen, but has since been localized as Nekketsu High School Dodgeball Club: Soccer Story.' FROM games WHERE igdb_id = 191639 ON CONFLICT (game_id, language_code) DO NOTHING;
