INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Final Zone II', 'You swore bloody vengeance when ZOD blew your satellite crew to shreds. Now it''s payback time! Your New Age Power Suits turn each member of your elite force into a walking arsenal of destruction, each with it''s own awesome fighting power. But you''re just five against a renegade weapons society responsible for killing billions! Choose the fighter best armed to face ZOD''s devastating forces in each level of combat as you fight battle after furious battle for the final zone!' FROM games WHERE igdb_id = 44314 ON CONFLICT (game_id, language_code) DO NOTHING;
