INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nekketsu Kouha Kunio-kun: Bangai Rantou-hen', 'Nekketsu Kouha Kunio-kun: Bangai Rantou-hen is the first game in the Kunio-kun series released by Technōs Japan for the Game Boy. It is a sequel to Nekketsu Kouha Kunio-kun, but uses the graphical style of Downtown Nekketsu Monogatari, which was previously released on the Famicom. This is the second game in the Kunio-kun series that has Kunio and Riki joining forces against a common threat, which would become a standard in later games.' FROM games WHERE igdb_id = 49075 ON CONFLICT (game_id, language_code) DO NOTHING;
