INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Horse Racing Simulator', 'Atari ST horse racing management/simulator game made by Budgie UK aka (Budgie Quality Software) and released back in 1990. Up to 5 players manage a stable full of horses, putting them into races and trying to figure out where they run best. Prize money is awarded for the top three horses, with a horse''s form also contributing to their value. The game is a precursor to Mark Loveday''s Starters Orders series.' FROM games WHERE igdb_id = 384548 ON CONFLICT (game_id, language_code) DO NOTHING;
