INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Les Manley in: Search for the King', 'The first in Accolade''s Les Manley series of adventure games, Search for the King begins with lovable nerd Les at a dead-end job rewinding video tapes at a failing TV station. The station pulls a publicity stunt offering a million dollars to anyone who can photograph "The King", and Les sees it as his chance to escape his job and impress the lady of his dreams. The search for the elusive legend takes Les across America – and places far beyond – on a colorful, humorous, and puzzling adventure.' FROM games WHERE igdb_id = 73837 ON CONFLICT (game_id, language_code) DO NOTHING;
