INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bases Loaded 3', 'Bases Loaded 3 is the third entry in the Bases Loaded series published by Jaleco for the Nintendo Entertainment System. It was released in 1990 in Japan, and 1991 in North America and was exclusively on the NES. The game departed from the two previous installments by removing seasonal play, focusing instead simply on individual exhibition games. It was noteworthy due to the endorsement of Ryne Sandberg, the famed baseball player.' FROM games WHERE igdb_id = 10124 ON CONFLICT (game_id, language_code) DO NOTHING;
