INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('horror-zombies-from-the-crypt', 12145, '1990-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co25b6.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Horror Zombies from the Crypt', 'As you take your first tentative steps beyond the decaying entrance gates of the Valdemar estate, your senses are alerted to an unknown fearful presence. You make haste to the apparent safety of the mansion house. The aged oak door slams shut behind you... Still trembling from your first encounter with the undead, and uneasy due to the enormity of your task, you decide to alert the local villagers by raising the flag over the West tower. The alarm raised - it''s only a matter of time before help arrives, or is it? As the moments pass you begin to feel a faint vibration in the earth beneath your feet. A mysterious force draws you towards a hidden cave entrance. You enter warily...With no hope of assistance it becomes clear that you alone must end the terror that torments the ancestral home. Leave no stone unturned in your quest for knowledge, be brave, be strong but most of all be lucky. As your knowledge of the fearful HORROR ZOMBIES increases, you realise that the means to their exorcism lies in gaining access to their stronghold ... the crypt. To find it''s entrance you must first challenge the sanctity of the family chapel. The point of no return, ahead lies the final conflict. Remember, here death is no release, you must be victorious or suffer an eternal fate.' FROM games WHERE igdb_id = 12145 ON CONFLICT (game_id, language_code) DO NOTHING;
