INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gem''X', 'This is a puzzle game that involves tiles of different colours, which must be manipulated to clear a succession of increasingly-difficult levels. You are presented with 2 sets of tiles, and must make the left one identical to the ''control'' set on the right. The colours are defined in a sequence - red, green, blue, purple, yellow - and when you click on a tile, that tile''s colour moves forward by two in that sequence (for example a blue one becomes yellow), whereas the tiles next to it move by one colour (for example, blue becomes purple).' FROM games WHERE igdb_id = 93210 ON CONFLICT (game_id, language_code) DO NOTHING;
