INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Treasure Trap', 'Treasure Trap is an isometric action game similar to Head Over Heels, but less abstract in its theme. The player guides the diver in a series of rooms (100 total) where the main goal is to collect gold. The main hazard encountered is the sea life that occupied the vacant ship. The character has no weapons, but carries a limited amount of "smart fishes", trained piranhas that attack and destroy all the enemies in the room.' FROM games WHERE igdb_id = 70936 ON CONFLICT (game_id, language_code) DO NOTHING;
