INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Igo Meikan', 'Igo Meikan ("Go Directory") is a go game for the Famicom released by Hect, a developer that specialized in board game to video game adaptations. It is primarily focused on teaching the player to play go like the pros, with the meikan (or directory) in this case being a list of techniques and tactics. As with all versions of go, the goal is to surround the opposing player''s pieces, thereby capturing them and removing them from the board. The winner is whoever has the most pieces on the board left when both players have stopped taking turns (usually because there''s no more legal moves).' FROM games WHERE igdb_id = 138706 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 138706 AND p.igdb_id = 99 ON CONFLICT DO NOTHING;
