INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Senda Salvaje', 'You are an adventurer who has learnt of the mysterious treasure of Eldorado, hidden in the temple of Mozteca deep within the jungles of South America. You must travel across marshland, mountains and jungles to reach the temple, fending off attacks by piranhas, eagles and even fire-breathing dragon spirits! Once you’ve found the entrance, you must explore the heavily guarded temple and locate the treasure.' FROM games WHERE igdb_id = 272301 ON CONFLICT (game_id, language_code) DO NOTHING;
