INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Golf', 'Welcome to MY GOLF! The latest state-of-the-­art golf simulation for your ATARI 2600. It''s amazingly real with rivers, sand traps, ponds, trees, roughs and out of bounds. Play alone or join a friend into a relaxing game of MY GOLF. But don''t be fooled, you need skill, strategy and great concentration.' FROM games WHERE igdb_id = 282738 ON CONFLICT (game_id, language_code) DO NOTHING;
