INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mundial de Fútbol', 'The world cup of Opera gathers the confrontations of the twenty-four teams which participated in Italy ''90, besides offering options of pre-world cup, training and demo mode. If we chose the last one, we will see the computer playing all the matches in the same order the FIFA fixed them. The programmers have also distributed the abilities of every team according to the world ranking position they were occupying in that moment.' FROM games WHERE igdb_id = 86008 ON CONFLICT (game_id, language_code) DO NOTHING;
