INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nightbreed: The Action Game', 'This is the first of a planned trilogy of games based on Clive Barker''s movie Nightbreed (the second game was Nightbreed: The Interactive Movie, and the third game was never released). This is a side-scrolling action game where Boone must fight his way through Midian, fighting the Sons of the Free and the Berserkers. There are five legs to Boone''s quest as listed in the manual' FROM games WHERE igdb_id = 15269 ON CONFLICT (game_id, language_code) DO NOTHING;
