INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Moai-kun', 'Moai-kun is a puzzle video game developed and published by Konami for the Family Computer in Japan in March 1990. The game derives its themes from Easter Island; the player controls a sentient moai statue that must rescue other moai and escape each stage via a door before the timer expires. Although platforming elements are present, the primary challenge is to find a way to manipulate the objects in each stage to reach the distressed moai and rescue them while still leaving an avenue of escape to the exit door.' FROM games WHERE igdb_id = 48424 ON CONFLICT (game_id, language_code) DO NOTHING;
