INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Roberta Williams'' King''s Quest I: Quest for the Crown', 'An "enhanced" version of the first game in the King''s Quest series released several years later which utilized the SCI (Sierra''s Creative Interpreter) graphics engine. It also included other improvements such as sound card support (with a corresponding in-game soundtrack) as well as an expanded story which alters some aspects of the original gameplay as a result. This version was included in several King''s Quest Collections over the years, often alongside the original version of the game.' FROM games WHERE igdb_id = 213153 ON CONFLICT (game_id, language_code) DO NOTHING;
