INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hero Shuugou!! Pinball Party', 'Hero Shuugou!! Pinball Party is a pinball game released for the Nintendo Game Boy. The player control the plunger and flippers from a pinball machine to handle the ball and aim for the highest score. There are two main modes, one featured in a 3-tier simple table and another featured in a more complex 3-tier table with different substages.' FROM games WHERE igdb_id = 228639 ON CONFLICT (game_id, language_code) DO NOTHING;
