INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fire and Forget 2: The Death Convoy', 'art two in the Fire and Forget series, best described as Crazy Cars (also by Titus) with weapons in a futuristic setting. This game combines the genres action and driving.  In each of the five levels you need to blow your way to the front of the death convoy and shot down the leader of a group of terrorists, who plans to blow up a city. Your machine of destruction is a car with the ability to fly.' FROM games WHERE igdb_id = 73184 ON CONFLICT (game_id, language_code) DO NOTHING;
