INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('che-guerrilla-in-bolivia', 15874, '1990-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/evdbptwittgreukkcqny.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'CHE: Guerrilla In Bolivia', 'CHE: Guerrilla In Bolivia is a strategic, simulation with action sequences. The game in inspired by the diaries of Che Guevara, which were kept during the campaign and start on November the 7th, 1966 in Camiri. Leading a guerrilla troop is a dangerous and demanding challenge. You must take on government troops and manage the daily survival of your followers. The simulation takes place across the whole of Bolivia, you have six detailed maps as used by Che himself. you will have to deal with ambushes, clashes with militia, sort out the food and provisions for your men, train any new recruits and run and a Guerrilla campaign. You start with 15 fighting men the core of Che Guevara''s operational unit. Guerrilla in Bolivia is two games in one, a sophisticated strategic simulation and an exciting adventure.' FROM games WHERE igdb_id = 15874 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 15874 AND c.slug = 'cases-computer-simulations' ON CONFLICT DO NOTHING;
