INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gumboots-australia', 221023, '1990-09-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5g8m.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scjag5.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gumboots Australia', 'You start with almost no money and must travel from town to town looking for answers. Travelling isn''t free of course so on the way you must do odd jobs to earn money to travel with car, bus, or airplane. Of course travelling with car or plane is the fastest but they''re also the costliest. You''ve gotta take into account how much time you still have to solve the mystery otherwise you might have to ask your bosses for an extension. You have about eight chances to extend your deadline but each extension takes away a bonus point. Use your time wisely and accept jobs that pay the highest for the least amount of days to get to your destination.' FROM games WHERE igdb_id = 221023 ON CONFLICT (game_id, language_code) DO NOTHING;
