INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bostilda', 'A.B. Cop is a futuristic 3D racing arcade game released by Sega in 1990.[3] Gameplay is similar to that of Chase H.Q..  The player takes on the role of the A.B. (Air Bike) Cop who must chase down and destroy the perpetrators of various crimes (which changes every level) before the time limit expires. A.B Cop introduced an element new to the racing genre: the end-of-level guardian.' FROM games WHERE igdb_id = 39882 ON CONFLICT (game_id, language_code) DO NOTHING;
