INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Evil Stone', 'Evil Stone is an odd game. It''s a beat em up, but rather than taking place on a traditional scrolling path, it takes place on grids of floating rocks. Furthermore, it''s a beat em up in which the player has no kind of health counter, and can theoretically take an endless number of hits without dying.' FROM games WHERE igdb_id = 40298 ON CONFLICT (game_id, language_code) DO NOTHING;
