INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nintendo Campus Challenge', 'Nintendo Campus Challenge is a special cartridge used in the events of the same name. There are two different cartridges produced for each event: a Nintendo Entertainment System version for the 1990 competition and a Super Nintendo Entertainment System cartridge for the 1992 competition. The cartridge is considered to be even rarer than the Nintendo World Championships cartridge with only one known to exist.' FROM games WHERE igdb_id = 94180 ON CONFLICT (game_id, language_code) DO NOTHING;
