INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'FurryMUCK', 'One of the earliest examples of a game catered toward and made by members of the Furry fandom, ''FurryMUCK'' is an online text-based roleplaying game which allows players to interact as their fursonas with others, as well as in various rooms and plazas.' FROM games WHERE igdb_id = 262192 ON CONFLICT (game_id, language_code) DO NOTHING;
