INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'King Neptune''s Adventure', 'One thousand years ago, on the equinox of the new star of Tritan, the golden crown of Polaris was stolen. And so it has been every 100 years, no matter what precautions were taken, no matter where the treasure was hidden, when the Star of Tritan appears, another treasure disappears. With the spirit of the seven seas to guide him, King Neptune must find the 8 stolen treasures and return the orb of peace to his undersea kingdom!' FROM games WHERE igdb_id = 48149 ON CONFLICT (game_id, language_code) DO NOTHING;
