INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wheel of Fortune: Featuring Vanna White', 'The all-new edition of Wheel of Fortune features Vanna White, the most popular game-show hostess ever and includes over 2,000 all-new Questions. New and enhanced graphics along with improved game play bring you the most exciting version ever of America''s favorite game show. Play against the computer, or against up to three friends. Spin the Wheel, buy a vowel, or attempt to solve the puzzle, only Vanna knows what lies behind the tiles. Watching your favorite game show is fun, but with GameTek''s WHEEL OF FORTUNE, you don''t just watch it, you live it!' FROM games WHERE igdb_id = 182279 ON CONFLICT (game_id, language_code) DO NOTHING;
