INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('little-league-baseball-championship-series', 48283, '1990-08-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6o35.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Little League Baseball: Championship Series', 'Little League Baseball! It''s the game every kid in America loves to play... And now you can experience the fun and excitement of Little League Baseball at any time of the year, rain or shine, day or night - right in your own living room! Create your own winning team of players with batting, fielding, pitching, and running characteristics you can tailor to your own specifications. Then challenge a friend or the computer to a worldwide Championship Series tournament. You are in full control of your players: Jump or dive for a tricky catch... Choose a full swing or a bunt for your batter... Shift fielders at will... Send in a pinch hitter or runner... Select a fast ball, slow ball, or curve ball for your pitcher... Steal a base if you dare... Or you might even try a squeeze play! Little League Baseball has been an American institution for 50 years - and you can be a part of it. If you''re a Little League fan or a Little League player - or if you ever wanted to be - here''s your chance to go for the glory!' FROM games WHERE igdb_id = 48283 ON CONFLICT (game_id, language_code) DO NOTHING;
