INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cadillac', 'Cadillac is a match-three card/puzzle game hybrid released by Hect first for the Japanese Famicom and later for the PlayStation. It uses a five by five grid in which the player must position playing cards in order to create sets of three, which are then removed. The game uses a casino theme, with the game grid resembling a green felt poker table.' FROM games WHERE igdb_id = 94896 ON CONFLICT (game_id, language_code) DO NOTHING;
