INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Poli Díaz', 'Poli Diaz is a boxing game protagonized by the Spanish boxing star of the late eighties, Policarpio Díaz. This game uses an isometric perspective where two boxers revolve around the center of the ring, with no possibility of going back, and we observe it from a corner of the quadrilateral. The options menu is the usual: one or two player mode, choose the control type and the number of assaults and lenght of the same.' FROM games WHERE igdb_id = 112871 ON CONFLICT (game_id, language_code) DO NOTHING;
