INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sanrio Carnival', 'Sanrio Carnival plays in the style of Columns and Dr. Mario, but features Hello Kitty and her friends. The player must match block objects of the same type in a horizontal or vertical row of three, four of five. The menu allows the player three different single-player styles of game which determines what goal must be met as well as options to choose a music track and theme of the blocks. There is also a two-player versus mode available.' FROM games WHERE igdb_id = 48638 ON CONFLICT (game_id, language_code) DO NOTHING;
