INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Oregon Trail', 'MECC released a DOS version of The Oregon Trail that was essentially identical to the Apple II version. However, the graphics had to be redrawn for the DOS version, using a different color palette and a slightly different resolution – and therefore screen shots of the DOS version are slightly different than the corresponding Apple II screen shots.' FROM games WHERE igdb_id = 213730 ON CONFLICT (game_id, language_code) DO NOTHING;
