INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '1000cc Turbo', 'Get in the saddle and ride in this great motorbike racing game! Choose from a variety of powerful bikes (including Enduro and Road Bikes) and race against some extremely tough opponents! Ride as fast as you can to the sound of stirring biking music - but ride to win! Great graphics, a variety of bikes, and addictive arcade action combine to make this a mega playable racing game!' FROM games WHERE igdb_id = 12347 ON CONFLICT (game_id, language_code) DO NOTHING;
