INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stunt Driver', 'Stunt Driver allows the player to control a ''60s Mustang car and take on three different opponents in a virtually unlimited amount of courses (thanks to the included course editor). The player''s driving style must be adjusted according to the opponent''s behavior. Drawbridges, loops, banked curves, hills and oil slicks are there to impede the player-controlled car''s progress. The game also features a replay camera complete with custom camera placement.' FROM games WHERE igdb_id = 93425 ON CONFLICT (game_id, language_code) DO NOTHING;
