INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Boxy Boy', 'The player controls the character "Rabi-Kun", and must push various crates over the yellow dots in order to complete the game''s fifty-five stages (divided into five "worlds") in that stage''s time limit. Rabi-Kun can only push the crates, and he cannot pull them; and should one of the crates reach an unmoveable position, the player may simply push the "reverse" button to undo one of the player''s moves. Should Rabi-Kun be trapped in an area and cannot get out, the player must push the "reset" button on the control panel, however this will not reset the timer; and should that timer reach zero, the game will be immediately be over.' FROM games WHERE igdb_id = 277524 ON CONFLICT (game_id, language_code) DO NOTHING;
