INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cosmic Fantasy: Bouken Shounen Yuu', 'One of the first Japanese RPGs in a CD format, Cosmic Fantasy: Bouken Shounen Yuu is a traditional representative of its genre, with party management, dungeon exploration, random enemy encounters, and turn-based combat. Characters fight using physical attacks, but later gain access to psychic techniques, which are equivalent to magic spells in comparable games. There are anime-style cutscenes with voice acting which advance the story.' FROM games WHERE igdb_id = 42005 ON CONFLICT (game_id, language_code) DO NOTHING;
