INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Venom Wing', 'Venom Wing is a weird mishmash of styles: You pilot a standard R-Type clone spaceship. Sometimes it turns into an eagle. Enemies include demons, robots, organic lifeforms, nondescript bouncing objects, and a gigantic dragon in space. The final boss is ED-209 from the Robocop movie.' FROM games WHERE igdb_id = 37210 ON CONFLICT (game_id, language_code) DO NOTHING;
