INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tel-Tel Mahjong', 'Tel-Tel Mahjong is a Sega Mega Drive Mahjong video game that was released exclusively in Japan in 1990. Part of the Tel-Tel series that included Tel-Tel Stadium, it was one of the few games that used the Mega Modem, allowing for two-player games via the Sega Net Work System. Up to three players can play the "host" player in addition to being able to play against computer opponents.' FROM games WHERE igdb_id = 4485 ON CONFLICT (game_id, language_code) DO NOTHING;
