INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rance II: Rebellious Maidens', 'Rance II: The Rebellious Maidens is the second game of the Rance Series, remade in 2009 and released in Alice 2010. The game is a turn-based dungeon crawler RPG with a top-down interface. Throughout the game, Rance may gain new party members, though further customization, such as organizing equipment, are unavailable for some.' FROM games WHERE igdb_id = 57642 ON CONFLICT (game_id, language_code) DO NOTHING;
