INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Virtual Valerie', 'She''s your cybernetic fantasy! You''ve got a hot date with Valerie! Explore Val''s "virtual world" and learn the true meaning of the term cybererotica! An intuitive point-and-click interface makes Virtual Valerie virtually yours to play with. She''s your cybernetic fantasy and you control the action! Hilarious rip-roaring entertainment in a sexploration adventure!' FROM games WHERE igdb_id = 280645 ON CONFLICT (game_id, language_code) DO NOTHING;
