INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ninja Remix', 'This is an updated version of "Last Ninja 2: Back With a Vengeance". The differences are a short intro, some minor graphic changes and a remixed soundtrack. Gameplay is exactly the same as in Last Ninja 2. Amiga and Atari ST version of Last Ninja Remix was a remake, with both graphical and sound enhancements, of The Last Ninja, first game of the saga, that was never published for 16 bit computers.' FROM games WHERE igdb_id = 12172 ON CONFLICT (game_id, language_code) DO NOTHING;
