INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Narco Police', 'The game is set in the future on a small island near the coast of Colombia . Here is the laboratory that produces the drugs for Colombian drug traffickers who rule the world. The Narco Police (anti-drugs police) have three of the five main tunnels get hands leading to the complex of the drug network. Typical in this game is that the perspective in the third person camera angle behind the counter-narcotics police.' FROM games WHERE igdb_id = 12694 ON CONFLICT (game_id, language_code) DO NOTHING;
