INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('megapanel', 45720, '1990-12-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/fiw82njoocyxpddf7tmv.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Megapanel', 'Megapanel (メガパネル) is a 1990 puzzle game developed and published by Namco (under their Namcot branding) for the Sega Mega Drive. Though initially released only in Japan, the game has made its way to the west through various compilations and consoles with built-in games. Megapanel is a sliding puzzle game similar to fifteen-tile puzzle games. The aim is to clear as many panels as possible before the pile reaches the top of the screen. In order to clear panels, three or more panels of the same color must be lined up together either vertically or horizontally. Use the D-pad to slide panels (each button indicates what direction to slide to, so the appropriate panel is automatically chosen) and A to bring the next row up immediately. A new life is awarded every 10000 points.' FROM games WHERE igdb_id = 45720 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 45720 AND ge.slug = 'puzzle' ON CONFLICT DO NOTHING;
