INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bad Lands', 'Bad Lands is effectively the spiritual successor to Atari''s previous racing games Super Sprint and Championship Sprint. Similarly to the Sprint titles, Bad Lands pits three cars against each other in a three lap race around a small, single-screen circuit. Bonuses are present in the form of wrenches which can be traded for goods such as extra speed, extra acceleration or better tires.' FROM games WHERE igdb_id = 39655 ON CONFLICT (game_id, language_code) DO NOTHING;
