INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chozetsu Rinjin Berabo Man', 'Chozetsu Rinjin Berabo Man is a platformer with underwater shoot ''em up stages, but the hero here doesn''t just use a gun - instead, his whole body is elastic, so you''ll find yourself taking out enemies with extending legs, arms and even neck! Along the way, you''ll pick up items from destroyed enemies. With a boss at the end of each level, a hero''s work is never done.' FROM games WHERE igdb_id = 42038 ON CONFLICT (game_id, language_code) DO NOTHING;
