INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dino Wars', 'Dino Wars is an exciting adventure game for two players. Each player controls a rampaging dinosaur. If you aren''t quick, you''ll find yourself ruthlessly attacked by your opponent. Gaining territorial rights is everything. Only the strongest can take command. It''s fast, furious and fun. You may use a 4K system, but best results are obtained on a 16K color computer.' FROM games WHERE igdb_id = 14648 ON CONFLICT (game_id, language_code) DO NOTHING;
