INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dick Tracy', 'Dick Tracy is a tie in to the 1990 movie adaptation of the classic comic strip. It is a side scrolling action game, where you control Dick Tracy as he moves through five stages, shooting gangsters with an assortment of weapons. The MS-DOS and Atari ST versions looks and plays the same, the main difference in those versions is their distinct music due to hardware and the complete lack of sound effect during gameplay.' FROM games WHERE igdb_id = 316839 ON CONFLICT (game_id, language_code) DO NOTHING;
