INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wizard Willy', 'Wizard Willy is a platform game released in 1990 for various 8-bit computers, where you set out on an adventure to rescue Fifi the Fairy, who has been kidnapped by an evil emperor. You climb and jump through the levels, collecting 10 magic eyeballs in each one, which you need to fight the Guardian Boss Skulls at the end of each area. You also have to avoid exploding traps. There are various pick-ups that will help you, by topping up your health, giving you more ammo, smart bombs, etc.' FROM games WHERE igdb_id = 71038 ON CONFLICT (game_id, language_code) DO NOTHING;
