INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pyro II', 'You play as a pyromaniac with a special system of burning down buildings: the night before you strike at a location, you hide gas cans all around the building. Then, the next day after all the people have left the building, you go to the top floor with a ball of cotton. You light it up and carefully go down the building floor by floor, picking up gas cans, pouring their contents all over the place, sometimes just running the fuse over them and letting them explode. This is depicted in ASCII graphics and using speaker sound.' FROM games WHERE igdb_id = 71863 ON CONFLICT (game_id, language_code) DO NOTHING;
