INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '9 Lives', 'Bob Cat has a girl in every town, but there is one who''s special to his heart; Claudette cat. Claudette has the biggest eyes you''ve ever seen and Bob aims to make her his queen. Off Bob goes to sing his night song, but arrives just in time to see his beloved being whisked away in a net by two of the mad Scientist''s men. What horrendous experiments will the Scientist carry out on old cutie paws? Can Bob save her in time?' FROM games WHERE igdb_id = 11879 ON CONFLICT (game_id, language_code) DO NOTHING;
