INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Danan: The Jungle Fighter', 'Danan, the infant who was rescued from the remains of a wrecked airplane by Jimba, a young Amazon tribesman, came home from hunting one day to find his guardian mortally wounded! What happened to Jimba? Who would do such a thing? Help Danan to find the answers — stalk the hot, wet jungles of the Amazon, putting the pieces together as you go, and avenge Jimba''s death!' FROM games WHERE igdb_id = 45664 ON CONFLICT (game_id, language_code) DO NOTHING;
