INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jack Nicklaus'' Unlimited Golf & Course Design', 'Jack Nicklaus'' Unlimited Golf & Course Design is a 1990 golf video game developed by Sculptured Software and published by Accolade for the Amiga and MS-DOS. It is the second in a series of golf games named after golfer Jack Nicklaus, following Jack Nicklaus'' Greatest 18 Holes of Major Championship Golf. The game includes the real-life Muirfield Village and the fictional game-only course "The Bear''s Track," both designed by Nicklaus. The game includes a golf course designer that allows the player to create customized courses.' FROM games WHERE igdb_id = 72175 ON CONFLICT (game_id, language_code) DO NOTHING;
