INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bloody Warriors: Shan-Go Troop Strikes Back!', 'You are a young man from an ancient village, which suffers from attacks by a vicious monster. You are assigned to find the monster''s lair and to defeat it. However, upon your return to the village you find out some people were abducted by the imperial troops. Now you have to find out the Empries''s true motives and to solve a grand mystery.' FROM games WHERE igdb_id = 48541 ON CONFLICT (game_id, language_code) DO NOTHING;
