INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shooting Gallery', 'Shooting Gallery is a simple game for DOS simulating a shooting gallery. You control mainly with the mouse to aim and try to hit targets to score points. The game is divided into 7 rounds where each round has a different shooting game or a little bit more difficult version of a previous round. Round 7 is always the Shootout which is a race against time to shoot as many badies as you can before the time limit runs out.' FROM games WHERE igdb_id = 218543 ON CONFLICT (game_id, language_code) DO NOTHING;
