INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('5-letter-kruiswoord', 92793, '1990-12-31', NULL, NULL, 'https://images.igdb.com/igdb/image/upload/t_1080p/scn46y.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '5-Letter-Kruiswoord', '5-Letter-Kruiswoord (5-letter-crossword in English) is a game in which the player solves a crossword that consists of only 5 letter words. The player can at any time check whether the answers he/she has given are correct. For every letter that is not filled in, the player gets 1 point. For every letter that is filled in wrong, the player gets 3 points. When the player does not know an answer, they can ask the computer for the right answer, but she will get 25 points. The objective of the game is to fill in the whole crossword with the right answers and get as few points as possible.' FROM games WHERE igdb_id = 92793 ON CONFLICT (game_id, language_code) DO NOTHING;
