INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mithos', 'After Ulises, Mithos is the second game published by Opera Soft based on the Greek mythology.  Mithos is a side-scrolling action game. In the game the player controls an archer centaur called Ahyzar, who must recover the seven lost magic coins of his god Krosar. To accomplish this the player must go through the Olympus. With only three lives to find the coins the player must try to avoid or destroy, all the mythological creatures that cross Ahyzar''s path.' FROM games WHERE igdb_id = 39102 ON CONFLICT (game_id, language_code) DO NOTHING;
