INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stormovik: Soviet Attack Fighter SU-25', 'Flight simulator for the Soviet SU-25 attack jet. A wide range of bombs and munitions are included (from cluster bombs to rockets to guns).  Includes three sets of missions (each set takes place in a year, from 1991 to 1993). Missions range from attacking tanks and troops to attacking bridges and other buildings. Although the missions can be played separately, played in order they form a storyline about the crumbling Soviet regime.' FROM games WHERE igdb_id = 79594 ON CONFLICT (game_id, language_code) DO NOTHING;
