INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Win, Lose or Draw', 'Win, Lose or Draw was a popular TV show requiring artistic skills and an ability to think laterally. A player on your team draws something on the big game board, and you must work out what it represents. They will be common expressions depicted literally, such as ''bright idea'' showing a light bulb over somebody''s head, and ''cabin fever'' as a rickety building next to a man with a thermometer in his mouth.' FROM games WHERE igdb_id = 48093 ON CONFLICT (game_id, language_code) DO NOTHING;
