INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Second Front: Germany Turns East', 'For the advanced wargamer, "Second Front: Germany turns East" is a division-level strategic game on a grand scale. The map extends from Berlin in the West to Stalingrad in the East, and covers the entire Russian Front. Players command over 150 German divisions and over 200 Soviet divisions, with asset information available to the individual tank, plane and infantry squad level.' FROM games WHERE igdb_id = 74107 ON CONFLICT (game_id, language_code) DO NOTHING;
