INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Paint School II', 'Paint School II has all the remarkable features of Paint School I: the use of 32,000 colors for spectacular painting, CD-quality music to color by, and sophisticated software for a "smart" program! Paint School II contains hundreds of additional scenes to paint, from such categories as Numerous Numbers, Lots of Letters and Shape Place. These subjects teach kids important concepts while they color. With a wide choice of color palettes and hundreds of scenes, there''s no end to the fun!' FROM games WHERE igdb_id = 46571 ON CONFLICT (game_id, language_code) DO NOTHING;
