INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sandy''s Circus Adventure', 'Sandy, the cuddly sea lion, is lost in the circus and your child is invited along! Together they can explore all the excitement, fun and adventure of the Big Top. They can romp with the clowns, get shot out of a cannon, disappear in a magician’s hat, play with jugglers and much, much more.' FROM games WHERE igdb_id = 45895 ON CONFLICT (game_id, language_code) DO NOTHING;
