INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mahjong-shikaku-retsuden-mahjong-wars', 37676, '1990-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6xil.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mahjong Shikaku Retsuden: Mahjong Wars', 'A dual Mahjong game/RPG from Nihon Bussan. Mahjong Shikaku Retsuden: Mahjong Wars ("Mahjong Assassin Chronicles: Mahjong Wars") is a PC Engine Mahjong game from Nichibutsu/Nihon Bussan, related to their Mahjong Triple Wars game. It features two modes: in one, the player takes on different opponents in one-on-one games, while in the other the player is walking around in an RPG world with party members and mahjong games as the "battles". The original Mahjong Shikaku game was released for the Arcades and MSX2 and is a "strip mahjong" game. This enhanced PC Engine version removes the nudity.' FROM games WHERE igdb_id = 37676 ON CONFLICT (game_id, language_code) DO NOTHING;
