INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pinball-jam', 40850, '1990-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6woe.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pinball Jam', 'Pinball Jam is a Lynx conversion of two pinball tables: "Elvira and the Party Monsters" (Midway, 1989), and "Police Force" (Williams, 1989). Both feature authentic table layouts, targets, and bonuses; the conversion of Elvira and the Party Monsters also features digitized sound effects, including the voice of Cassandra Peterson (Elvira). Each table scrolls up and down during gameplay (as opposed to just "snapping" to a new area as the ball reaches it).' FROM games WHERE igdb_id = 40850 ON CONFLICT (game_id, language_code) DO NOTHING;
