INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dekoboko Densetsu: Hashiru Wagamanma', 'Dekoboko Densetsu is a humorous game that combines elements of arcade action and racing. Up to five players can compete in the races. All the stages are vertically-scrolling (top-down), with the cars represented as small sprites of different colors. The player''s goal is not only to beat the other cars, but also reach the finish line safely: each car has limited hit points, and continuously receives damage during the race.' FROM games WHERE igdb_id = 145674 ON CONFLICT (game_id, language_code) DO NOTHING;
