INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wolfpack', 'Wolfpack is a World War II submarine simulator published by Brøderbund in the 1990s, for Amiga, Atari ST, MS-DOS, and Macintosh. It simulates combat actions between wolf packs of German U-boats and convoys of Allied destroyers and merchant vessels in the Battle of the Atlantic.' FROM games WHERE igdb_id = 100177 ON CONFLICT (game_id, language_code) DO NOTHING;
