INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Oxyd', 'Oxyd is a 1990 puzzle game developed for the Atari ST and ported to the Amiga, Macintosh, MS-DOS, and the NeXT platform by Dongleware Verlags GmbH. It is a game of puzzles and tests to restart all the oxygen generators on the player''s home planet.' FROM games WHERE igdb_id = 18867 ON CONFLICT (game_id, language_code) DO NOTHING;
