INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beverly Hills Cop', 'Beverly Hills Cop is a video game developed by Tynesoft and published in 1990. The story is loosely based on the 1984 film Beverly Hills Cop. The player controls Axel Foley in four distinct sub-games: a side-scrolling action game, a driving game, an overhead view shooter, and a first person shooter. The game was released on Commodore 64, ZX Spectrum, BBC Micro, Amstrad CPC, Amiga, Atari ST, and MS-DOS. The BBC version only contains the driving game.' FROM games WHERE igdb_id = 11956 ON CONFLICT (game_id, language_code) DO NOTHING;
