INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Power Blazer', 'The player takes control of Steve Treiber, a highly trained soldier on a lone mission behind enemy lines. He is the only one capable of taking Brain Master offline and to save the world. Our young hero is armed with a powerful combat-boomerang called the ''Power Blazer''. The game was later westernized as Power Blade.' FROM games WHERE igdb_id = 48568 ON CONFLICT (game_id, language_code) DO NOTHING;
