INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Timeball', 'Get wrapped up in this mind-bending game that will test your mental agility. The action seems simple -- just keep a ball rolling through a winding maze by shifting around pieces of tubing. But the action is intense! Race against time and the track to keep the ball from crashing. There are 100 challenging levels -- plus the unique edit feature lets you build your own puzzles!' FROM games WHERE igdb_id = 7791 ON CONFLICT (game_id, language_code) DO NOTHING;
