INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Magic Johnson''s Fast Break', 'DRIVE, PASS, SHOOT, SCORE! Now you can slam dunk like the pros!Magic Johnson''s Fast Break is slammin'' jammin'' basketball action. Play against the computer or an opponent. Up to four players can play simultaneously. Head for the hoop and slam dunk the ball! The better you get the better your salary gets! Simple enough for beginners, challenging enough for pros. Shoot free throws, 3-pointers, execute special plays, and more! Master all five levels of this ultimate basketball contest!' FROM games WHERE igdb_id = 48180 ON CONFLICT (game_id, language_code) DO NOTHING;
