INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ADI Maths: 12/13 Years', 'A series of educational games for children by Coktel Vision. It''s a short French acronym for "Accompagnement Didacticiel Intelligent" meaning Intelligent Accompaniment Tutorial. The franchise was also adapted into comic books, music and television series. There are several categories of games based on different age groups: - Adi is a character designed for 10-14 year-olds - Adibou is for 4-7 year-olds - Adiboud''chou is for 18 months-3 year-olds Adi is an alien with an orange skin and pointy ears. He is driving the children through the exercises and the mini-games. Mini-games can be unlocked when a sequence of exercises has been successfully done.' FROM games WHERE igdb_id = 14221 ON CONFLICT (game_id, language_code) DO NOTHING;
