INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crime Wave', 'Crime Wave is a side-scrolling shooter with certain similarities to Narc in tone and gameplay. Controlling a police officer, the player shoots his or her way through slums, inner cities, and other locations, trying to destroy a powerful criminal organization and save the President''s gorgeous, young, and single daughter. The game features digitized graphics.' FROM games WHERE igdb_id = 12018 ON CONFLICT (game_id, language_code) DO NOTHING;
