INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'King of Casino', 'The chips are down as you and your buddies travel to Vegas in this high stakes adventure. Match wits (and luck!) against the house or up to four of your friends in a game with all the glitz and glamor of a real casino. Play Poker, Blackjack, slot machines, Keno or Roulette. Choose one of 15 different casinos. You''re the odds-on favorite in this high-rolling gambling simulation.' FROM games WHERE igdb_id = 42105 ON CONFLICT (game_id, language_code) DO NOTHING;
