INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ultimate-basketball', 48266, '1990-10-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6oya.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8h9t.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ultimate Basketball', 'Shoot some hoops with Ultimate Basketball. All of the traditional rules of basketball apply as you take control of a fictional team from one of seven American locales. Each team has its own full roster of players as well as unique strengths and weaknesses. For example, Houston has a tight defense and can shoot the three, while Dallas excels at the passing game. The point of view is horizontal for the most part. Occasionally, you will get a close-up action scene on plays such as slam dunks and free throws. There are also two different play modes, "Tournament" and "One Game." You can play by yourself, against a friend, or with a friend against the computer.' FROM games WHERE igdb_id = 48266 ON CONFLICT (game_id, language_code) DO NOTHING;
