INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sokoban-world', 38102, '1990-04-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6xoy.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sokoban World', 'Pushing around boxes in store rooms may not sound like ideal fodder for a video game. Well, they went and made one anyway. this is one of those brain melting puzzle games that some will love and some will despise. Each level you are presented with a room with boxes and spots, which are where the boxes should end up. You can push the boxes, but not pull them and you really have to plan in advance to stop getting, um...''boxed'' in. If you feel you''ve taken a bit of a wrong turn, you can simply push a button and rewind your moves. But as well as countless levels of box-shoving there''s also a level editor that allows you to create your own levels of fun and frustration. (From The PC Engine Software Bible)' FROM games WHERE igdb_id = 38102 ON CONFLICT (game_id, language_code) DO NOTHING;
