INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heavyweight Championship Boxing', 'Once the player chooses a boxer, the other challengers must be defeated in order to gain the title. Points can be distributed and re-distributed on the fighter''s health meter, stamina, and how fast he moves around in the ring. Either uppercuts or normal punches can be used to wear down the opponent in the game.' FROM games WHERE igdb_id = 48981 ON CONFLICT (game_id, language_code) DO NOTHING;
