INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kamikaze', 'Using buttons to move left, right and fire, you attempt to ward off invading aliens and their flying saucers. The aliens are dropped off from a saucer and stored in multiple columns until a column is full, then the aliens in that column descend, one by one, and attack. Also, the saucers sometimes descend to attack; if they are not destroyed, one ship is lost.' FROM games WHERE igdb_id = 12651 ON CONFLICT (game_id, language_code) DO NOTHING;
