INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Golfamania', 'You''ll need sharp eyes, a smooth swing, and perfect judgment if you''re going to master Golfamania. Out on the links you''ll have to consider the distance, the wind, the lie of the ball, where to hit the ball and which club to use. Then watch that power meter and swing for the pin!' FROM games WHERE igdb_id = 45673 ON CONFLICT (game_id, language_code) DO NOTHING;
