INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Anarchy', '"Whether you liked or loathed Defender, you''ll love Anarchy. The speed at which the screen scrolls is frightening, the number of aliens, bullets and other miscellaneous objects that are animated simultaneously is absolutely remarkable. Anarchy is the best version of Defender ever." Full screen horizontal, 4 level parallax scrolling. Arcade running speed (50 frames per second) on Amiga and Atari ST. 48 Colors on screen at once. Up to 80 aliens attacking simultaneously. Full screen animation sequences totalling over 450 screens. 4 Channel sampled soundtrack. Saveable top 50, Hi-Score table. Fast, frantic, furious gameplay.' FROM games WHERE igdb_id = 14163 ON CONFLICT (game_id, language_code) DO NOTHING;
