INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Meimon! Tako Nishi Ouendan', 'Meimon! Tako Nishi Ouendan is a strategy game released exclusively in Japan for the NES (Famicom) in 1989, and is based on Juzo Tokoro''s 1984 manga series of the same name (which was also adapted into a anime motion picture in 1987). Players control a gang of "ouedan" who must battle their way back to their turf after being ambushed on an island.' FROM games WHERE igdb_id = 48779 ON CONFLICT (game_id, language_code) DO NOTHING;
