INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Omega Zone', 'Fast paced shoot-em-up by Peter Curtis that was released on Crash! Presents 20, the cover cassette that came with Crash! magazine, issue 84. The game is played in 3D, with your being just behind your Skimmer craft. You have to battle the enemy craft, whilst also avoiding plasma pillars that dot the landscape. If you manage to survive, there are ten levels before the end of the game.' FROM games WHERE igdb_id = 237833 ON CONFLICT (game_id, language_code) DO NOTHING;
