INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Belloncho Body Inspection', 'You are Nanako Hongou, a new transfer student to the all-girls school, St. Belloncho Academy. Hearing rumors of a sketchy body inspection taking place at the school infirmary, you decide to take it upon yourself to unearth the culprit, and expose the secrets of St. Belloncho Academy. Fight an eclectic cast of delinquents while going about your school life and solving mysteries.' FROM games WHERE igdb_id = 264657 ON CONFLICT (game_id, language_code) DO NOTHING;
