INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'City Hunter', 'City Hunter is a side‑scrolling action game starring private eye Ryo Saeba, based on the manga and anime. Exclusive to the PC Engine, it mixes exploration and shooting across four chapters as Ryo checks doors for mission‑critical NPCs and items while fending off thugs. The game features series characters like Kaori Makimura, Umibozu, and Seiko Nogami, and captures Ryo’s mix of lechery and sharp investigative skill.' FROM games WHERE igdb_id = 37718 ON CONFLICT (game_id, language_code) DO NOTHING;
