INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'European Superleague', 'Up to eight players can manage one European team on one of three difficulty levels. The player''s responsibilities are training, scouting, transfers, press speeches and team strategy (this is the best part of the game, lots of tactics). Each team has 20 players with different skill that change throughout the season, so the player has to select the starter eleven for every match' FROM games WHERE igdb_id = 13059 ON CONFLICT (game_id, language_code) DO NOTHING;
