INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('high-impact-football', 40061, '1990-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7jhf.jpg', NULL, NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'High Impact Football', 'The players must use an 8-way joystick and a single button to control their currently-selected players - and there are over 40 offensive plays and defensive formations to choose from (including "Bombs", "Double Reverses", "Half-Back Options", "Nickel Defense", "Zone Coverage", "Stunts" and "Red-Dog Blitz"), making the game more complex than Midway''s Pigskin 621 AD (which was released earlier in 1990 but it only allowed two players to play it simultaneously). The game also features cheerleaders, coaches, commentary by an insane play-by-play announcer called "Manic Max", and a crowd of fans who cheer or jeer at the players, based on their performance (the leader of whom is "Joe Six-Pack").' FROM games WHERE igdb_id = 40061 ON CONFLICT (game_id, language_code) DO NOTHING;
