INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wraith', 'Wraith is a fantasy role-playing game like the author''s previous effort Shadowforge, although it''s set in a larger, more detailed world with an updated and expanded rule system. The worship of Metiria is being subverted all over the realm of Araithia; lords and commoners have turned their devotion to a newly-arrived evil power, the Wraith, whose monstrous armies now infest the island. You, guardian of the last Temple of the True Faith, are summoned to seek out and eliminate this evil.' FROM games WHERE igdb_id = 233337 ON CONFLICT (game_id, language_code) DO NOTHING;
