INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yamamura Misa Suspense: Kyoto Zaiteku Satsujin Jiken', 'The third and final Yamamura Misa Suspense game, published for the NES in 1990. Yamamura Misa Suspense: Kyouto Zaiteku Satsujin Jiken is the third and final Japanese murder-mystery game in the Yamamura Misa Suspense series of video games developed for the Nintendo Entertainment System by TOSE and published by HectorSoft in 1990. The player takes the role of a detective as they attempt to solve a murder case by travelling across a city, interrogating suspects and witnesses. Gameplay mostly comprises of selecting actions through menus or selecting items shown on screen to interact with similar to many point-and-click adventure games.' FROM games WHERE igdb_id = 48869 ON CONFLICT (game_id, language_code) DO NOTHING;
