INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Pro Yakyuu', 'The Pro Yakyuu is a baseball game that allows players to compete in Japan''s professional baseball league, with licensed team and player names. Versus mode allows competition between two players; in a friendly game, the computer AI chooses an opponent for the team selected by the player; the "Open" mode is a tournament in which players can assign controllable teams to themselves and to the AI. The game itself can be set on "Action", "Simulation", or "Auto" mode, with varying degrees of realism. Pitchers and batters are controlled from a third-person view, while baserunning is viewed from an overhead perspective.' FROM games WHERE igdb_id = 132129 ON CONFLICT (game_id, language_code) DO NOTHING;
