INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('super-skweek', 39066, '1990-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3cu7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/aruzg.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Skweek', 'Super Skweek is a game inspired by the wide success of Chip''s Challenge, and shares some elements of that puzzler while combining other elements from games such as Pengo. In Super Skweek, you play the title character who must walk around and either paint all the tiles of the game board pink, complete a specific mission, or both. Some tiles react in various ways when you walk on them, like exploding. Unlike Chip''s Challenge, the game plays in realtime and you can pick up and use weapons to keep away certain monsters as you paint the tiles. There is also a shop you can enter to purchase items. Finally, levels have a time limit for completion.' FROM games WHERE igdb_id = 39066 ON CONFLICT (game_id, language_code) DO NOTHING;
