INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Baseball Stars Professional', 'Baseball Stars Professional is the follow-up to Baseball Stars for the Nintendo Entertainment System, and features comic-style graphics. Choose from a variety of teams that include Celestial Planets, Heavenly Bodies, Shadow Demons, Battle Knights, Fabulous Superstars, and many others. Then select the field where the game is to be held: The SNK stadium or the SNK dome. Each field has the same dimensions, but their capacity varies. The game is played the same way as normal baseball. Features a VS. mode in which two players can play against each other.' FROM games WHERE igdb_id = 39595 ON CONFLICT (game_id, language_code) DO NOTHING;
