INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Thunder & Lightning', 'A "Breakout" type game with interesting characters such as Mr. Chin and the Thunder Warrior. Mr. Chin holds a stick over his head that acts as the paddle. If your ball hits one of the power-up carriers (Flying Saucer, Submarine or Airplane) you have to try and pick up the released power-up while continuing to keep the ball in play.' FROM games WHERE igdb_id = 48273 ON CONFLICT (game_id, language_code) DO NOTHING;
