INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battle Pingpong', 'Battle Ping-Pong is a Game Boy game revolving around ping-pong (or table tennis as it is generically called). One person on either side of a small table with a net return a ball back and forth in a rally until the ball is either dead in play or bounces off the table.' FROM games WHERE igdb_id = 7774 ON CONFLICT (game_id, language_code) DO NOTHING;
