INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('deathbots', 48138, '1990-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6nuj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/xxeho60pi8qauadrx9ho.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deathbots', 'The Mutech Corporation has created their Gamma Base on what used to be Alcatraz Island. Their attempts at creating computer intelligence has backfired, as the AI they''ve created has taken over the computer systems and is threatening the world! Deep in the fortress is a gamma bomb, and your goal is to penetrate the fortress to destroy the bomb before it can be used. But be careful, for many Deathbots are guarding the maze-like passageways leading to the bomb! Gameplay is from an overhead point of view; you''ll need to find your way through the various passageways to reach the gamma bomb (located on the 8th level) and diffuse it. In addition to doorways and walls, transporters can also be found in the maze. These will instantly teleport you to a new location, and on many levels you will need to figure how to use them correctly to get past otherwise dead ends. Different types of Deathbots guard the passages; and you''ll need to use the various weapons you find lying about to get past them, before they destroy you. You have a limited amount of energy. Each time you are hit by enemy fire or by a Deathbot, your energy depletes. Lose all of of your energy and a life is lost. And of course, each level ends with a large boss Deathbot. Good luck on your mission!' FROM games WHERE igdb_id = 48138 ON CONFLICT (game_id, language_code) DO NOTHING;
