INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bardarts', 'Bardarts is a one or two player, shareware darts game that is based on the classic pub game of 301. In this game the player must finish on a double and the game uses the darts standard ''bust'' rule, i.e. if a player''s score goes below zero then all scoring darts in that turn are discarded and their score is reset.' FROM games WHERE igdb_id = 141222 ON CONFLICT (game_id, language_code) DO NOTHING;
