INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nippon Ichi no Meikantoku', 'Nippon Ichi no Meikantoku is a baseball management game, where you take control of a team and manage it by controlling the player training and various other aspects of the team. You can watch games being played out and make changes during the match, such as changing the pitcher, outfield player positions and batting order. You start the game by creating your manager and entering your name, then you get a randomized number of attribute points to distribute for four different categories. After that, you choose a team to manage and five other teams to play against.' FROM games WHERE igdb_id = 48803 ON CONFLICT (game_id, language_code) DO NOTHING;
