INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Olli & Lissa 3: The Candlelight Adventure', 'Olli and Lissa 3 is an action platform game where you have to piece together your sabotaged car by searching for the parts in various rooms of your house. You need a magnifying glass to be able to search the rooms, and if you manage to find a car piece, you then need to find a spanner and head to the basement to put the car part in place. There are various pick-ups that will help you on your quest, and also telephones which will give a hint about which direction to head for the next car piece. It is the third game in the Oli and Lissa series.' FROM games WHERE igdb_id = 70920 ON CONFLICT (game_id, language_code) DO NOTHING;
