INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gettysburg', 'Pegged as "an interactive battle simulation", Gettysburg is a real-time strategy game released by Swfte International in 1993 and co-produced with Turner Interactive. Coming on two floppy disks, players get to experience the famous historical battle while potentially changing its outcome.' FROM games WHERE igdb_id = 14895 ON CONFLICT (game_id, language_code) DO NOTHING;
