INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Veigues Tactical Gladiator', 'For 3 years, alien invaders have been pounding the earth into a smoldering ruin. There isn''t a man alive who can stop them. But now, there''s Veigues, a devastating fighting machine! Built with captured enemy technology, he''s our last desperate hope for survival ... and you''re in control! Trash the invaders with the Plazma Cannon! Just keep your firepower hot and fight like there''s no tomorrow. Destroy the aliens or there won''t be!.' FROM games WHERE igdb_id = 37733 ON CONFLICT (game_id, language_code) DO NOTHING;
