INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Galaxian3: Project Dragoon', 'Galaxian3: Project Dragoon is a 3D rail shooter video game developed and published by Namco. It was originally a theme park attraction designed for the International Garden and Greenery Exposition (Expo ''90) in Japan, and was later released as an arcade game in 1992. The game involves players controlling a starship named the Dragoon in its mission to destroy Cannon Seed, a superweapon set to destroy what is left of the human race.' FROM games WHERE igdb_id = 140478 ON CONFLICT (game_id, language_code) DO NOTHING;
