INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mug Smashers', 'Mug Smashers is an early 90''s western-developed two-player arcade brawler that''s basically a combination of Combatribes and Final Fight. It has suspiciously similar sprites and music to the former but plays more like the latter with its scrolling stages and lack of ground attacks or tornado throws. It has an absurd visual style including a main character that''s wearing red leopard pants and white sunglasses.' FROM games WHERE igdb_id = 148075 ON CONFLICT (game_id, language_code) DO NOTHING;
