INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('james-buster-douglas-knock-out-boxing', 46530, '1990-07-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/sq4oozb4fiqqdcxtd5az.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc6cn1.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'James ''Buster'' Douglas Knock Out Boxing', 'Final Blow is an action game based around the sport of boxing. You can play the fighters in a sequence of knock-out competitions, (the computer versions also include a round-robin league). Rounds last one minute, with a short break in between them. As in the real sport, your aim is to knock your opponent down for 10 seconds, by gradually weakening him with a series of punches. You can block punches, to avoid them inflicting damage onto you. The ring is of a limited size, so players can be cornered, although the referee will intervene to break the boxers up if they become entangled in a stalemate position.' FROM games WHERE igdb_id = 46530 ON CONFLICT (game_id, language_code) DO NOTHING;
