INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Earth Shaker', 'In the style of Boulder Dash and Repton, Earth Shaker sees you as a small robot scuttling around an underground land of manic mayhem. Your job is to collect all the on-screen diamonds, digging your way through the soil and dodging the stones and stuff that get dislodged and drop on your head (or not as the case may be).' FROM games WHERE igdb_id = 46042 ON CONFLICT (game_id, language_code) DO NOTHING;
