INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Life & Death II: The Brain', 'The Brain follows the same premise as its predecessor Life & Death, wherein the player controls an up-and-coming surgeon who must perform simulated surgery on patients with varying problems. The sequel focuses on the brain, whereas the first game focused on the abdomen.' FROM games WHERE igdb_id = 121164 ON CONFLICT (game_id, language_code) DO NOTHING;
