INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Prehistoric Tale', 'A Prehistoric Tale is a non-scrolling 2-D platformer. Kill enemies by jumping on them. Alternately, hatched dinosaurs can be temporarily caged by jumping over them. This game is essentially a remake of Dino Eggs for the Commodore 64.' FROM games WHERE igdb_id = 15347 ON CONFLICT (game_id, language_code) DO NOTHING;
