INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Astate: La Malédiction des Templiers', 'Astate is a French icon based point and click adventure game.  You play as an archaeologist that has to to search the French countryside and its Templar ruins for all the pieces to a missing statue. Collecting a statue part will advance the game via cutscene.' FROM games WHERE igdb_id = 14271 ON CONFLICT (game_id, language_code) DO NOTHING;
