INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('matrix-marauders', 15259, '1990-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co86xu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc656p.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Matrix Marauders', 'Earth One- Prepare to descend. Your time has come... As you hurtle through the complex mazes of the death tunnels, you must negotiate the tortuous twists and turns in order to keep ahead of the competition. The deadly race track is linked by a series of pit grids which are littered with numerous bonuses including speed amplification modules and fuel which must be collected to ensure your survival! Featuring a unique 3D arcade game concept. This is the ultimate futuristic racing simulator- you won''t find anything like this on this side of the galaxy! Option two player "Head to Head" link via serial port. Digitized audio navigational aid. Dedicated weapon selection feature. Your mission? To emerge victorious as Annihilator One- and so to be the elite Intergalactic Screaming Race Skull Team... can you meet the challenge???' FROM games WHERE igdb_id = 15259 ON CONFLICT (game_id, language_code) DO NOTHING;
