INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Power Mission', 'Thrilling War Simulation Game Power Mission simulates a realistic sea battle against a powerful enemy force. Select and deploy one of seven fleets and then destroy the enemy using radar, missiles and various weapons. Power Mission has 10 stages and the enemy gets stronger and stronger. Prepare yourself for this challenging, strategic, Game Boy game!' FROM games WHERE igdb_id = 49089 ON CONFLICT (game_id, language_code) DO NOTHING;
