INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crossbow: The Legend of William Tell', 'You play William Tell, a hero in his homeland; a symbol of freedom looking for justice. To the Emperor though he is a dangerous spark that must be extinguished. To the resistance he is a figurehead, a powerful ally, if only they can persuade him to join with them. Aim well, the hopes of many are on your shoulders.' FROM games WHERE igdb_id = 14631 ON CONFLICT (game_id, language_code) DO NOTHING;
