INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tangram', 'CD-I makes Tangram more challenging, more exciting. There are more symbols, more silhouettes, so you can develop greater skills. Just use the cursor to rotate and move the pieces. Choose free expression or tackle set tasks. And choose your own level of play: beginner, intermediate, advanced, expert - up to the highest level of all. Free Form Tangram on CD-I means moving forms, mood music, and much more fun!' FROM games WHERE igdb_id = 12499 ON CONFLICT (game_id, language_code) DO NOTHING;
