INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Drop Off', 'There''s no waking up from this nightmare! You''ll need all your nerve and strategy to get out alive! A dream of giant apples and diamonds goes berserk when they turn into deadly demons raining down on your head! You have to shoot ''em down with a steel ball. Ricochet your shots to knock ''em off in bunches! They''re coming fast, and each level is more threatening than the last! Why are those skulls laughing? Shoot first and ask questions later!' FROM games WHERE igdb_id = 42108 ON CONFLICT (game_id, language_code) DO NOTHING;
