INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NES Play Action Football', 'Nintendo takes its game to the gridiron with NES Play Action Football. While Nintendo did not get the NFL license for this one, it did secure the license of the NFL Player''s Association, so the 8 teams to choose from (all named after the appropriate NFL cities) are all stocked up with real pro players from the 1989 season. You can even substitute second-stringers for the "skill" positions (QB, RB, WR, TE, and FS/SS) when your starters get tired.' FROM games WHERE igdb_id = 48194 ON CONFLICT (game_id, language_code) DO NOTHING;
