INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wings of Death', 'Wings of Death is a 1990 shoot ''em up video game developed by Eclipse Software and published by Thalion Software, released originally for the Atari ST and then ported for the Amiga. Its working titles were Wings of War and Spellbinder. Wings of Death is a vertically scrolled shooter in a fantasy scenario in which the player controls a mage turned into a winged creature on a quest to defeat a wicked witch. The game was well received and was followed by the science fiction themed sequel Lethal Xcess in 1991.' FROM games WHERE igdb_id = 20893 ON CONFLICT (game_id, language_code) DO NOTHING;
