INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-cliffhanger-edward-randy', 39927, '1990-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobd0j.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/swvwydybcmt2ykyfryx2.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Cliffhanger: Edward Randy', 'A fast moving platform game in which the player controls the Indiana Jones-esque and unfortunately named ''Edward Randy''. The levels are an inventive mix of standard platform action and 3-D scrolling levels; the latter usually having the player driving a jeep and repelling the enemy attacks. The game is based on the archetypal Hollywood action blockbuster and features a filmic score to back up the on-screen action. The player''s only weapon is a whip - another nod to the Indiana Jones character - which can be used to both attack enemies and as a ''rope'', to enable the player to reach distant platforms.' FROM games WHERE igdb_id = 39927 ON CONFLICT (game_id, language_code) DO NOTHING;
