INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('trio-the-punch-never-forget-me', 39714, '1990-05-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1iuc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scmwa2.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trio the Punch: Never Forget Me', 'Trio The Punch is a beat ''em up game where the player chooses a character from three playable characters, and fights numerous enemies across a side-scrolling game screen. Most of the levels are played scrolling to the right, but some loop around the left and right edges of the screen. Other levels allow the player to scroll upwards or downwards by jumping, while some do not contain scrolling at all. The game is completed when the player finishes all 35 levels. The player controls their character with an 8-way joystick and 3 buttons (attack, jump, and special attack). Certain enemies leave behind a heart on the screen after being defeated, and collecting the required number of these hearts for each level causes a boss to appear, who must be defeated in order to complete the level. However, bosses appear from the start in some levels, so hearts do not always need to be collected.' FROM games WHERE igdb_id = 39714 ON CONFLICT (game_id, language_code) DO NOTHING;
