INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pesterminator: The Western Exterminator', 'Have a smashing good time! When you''re bugged by nasty pests, it''s time to call Kernal Kleanup, the familiar character from Western Exterminator. Ronnie, the super rat, and his friends are pushing for a hostile takeover and their territories cover Houses, Office Buildings, Warehouses, Hotels, Swamps, and even the Moon. Watch out bugs, PESTERMINATOR has a big surprise waiting for you!' FROM games WHERE igdb_id = 48080 ON CONFLICT (game_id, language_code) DO NOTHING;
