INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kujaku-ou II', 'The adventure continues as Peacock faces the incarnation of general Nobunaga Oda. Team up with Asura, a fiery spirit, Jukindo master Onimaru, and Zen master Kou Kaifou to fight Nobunaga''s missionary minions with a vast array of Shingon spells! Travel to the mystic world of the Lotus mandala and defeat Hindu demons, dark boddhisattvas, and the shadowiest villain yet, the Phoenix!' FROM games WHERE igdb_id = 48439 ON CONFLICT (game_id, language_code) DO NOTHING;
