INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kore ga Pro Yakyuu ''90', 'A baseball game for the PC Engine that features athletes and teams from the 1990 Nippon Professional Baseball league.  Kore ga Pro Yakyuu ''90 ("This is Pro Baseball ''90") is a PC Engine exclusive baseball game and the sequel to Kore ga Pro Yakyuu ''89. It did not see a sequel. It features twelve teams and their players from the official Nippon Professional Baseball organization.  Kore ga Pro Yakyuu ''90 is a traditional 16-bit baseball game. The camera is positioned behind the batter, with cutaways showing other players on the bases. The pitching player can also use this view to change the formation of their fielders before the next pitch. Once the ball connects with the bat, the view switches to a distant top-down view so that the player can manage their fielders.' FROM games WHERE igdb_id = 37686 ON CONFLICT (game_id, language_code) DO NOTHING;
