INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Galaxy 5000', 'The future of Grand Prix racing is in outer space. And you''re one of the hottest turbo-racers in the solar system. But are you tough enough to win the ultimate racing challenge, the GALAXY 5000? Dozens of track objects, including land mines, gun turrets, speed zappers, warp doors and deadly solar spikes! Awesome digitized sound effects. Hear the driver scream as he falls off the track. Use your winnings to repair damage, or upgrade to a more powerful turbo-craft!' FROM games WHERE igdb_id = 48120 ON CONFLICT (game_id, language_code) DO NOTHING;
