INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Magician', 'Magician is a 2D, side-scrolling action RPG. As Paul, you must travel through towns, have conversations with non-player characters, acquire and manage inventory (food, water, weapons, potions, etc.), learn magic spells, fight battles, and solve puzzles. Your ultimate goal: collect each of the four elemental vials -- earth, air, fire, and water -- and combine them to create the Ultimate Potion. Only then can you hope to vanquish the evil wizard Abadon!' FROM games WHERE igdb_id = 94209 ON CONFLICT (game_id, language_code) DO NOTHING;
