INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Genshi Tou 1930''s', 'You are investigating the suspicious pre-historic islands, to find out why so many people who visited this place, have gone missing. You take control of a plane. While flying above the mysterious island you face many pre-historic animals as enemies. There are many Wild humans below on the ground as well, who try to catch onto your plane if you fly too low. Dinosaurs still exist!!' FROM games WHERE igdb_id = 38653 ON CONFLICT (game_id, language_code) DO NOTHING;
