INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Golf', 'Golf, also known as One Foundation, is a patience or solitaire card game where players try to earn the lowest number of points (as in golf, the sport) over the course of nine deals (or "holes", also borrowing from golf terminology). It has a tableau of 35 face-up cards and a higher ratio of skill to luck than most other solitaire card games. It was included as part of Microsoft Entertainment Pack in 1990 for Windows PCs.' FROM games WHERE igdb_id = 282126 ON CONFLICT (game_id, language_code) DO NOTHING;
