INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Challenge of the Dragon', 'Are you the savior spoken of in the ancient legend? Only your Dragon Style blend of sword and martial arts can save you now... Your girlfriend has been kidnapped by the dark necromancer. Lightning sears the skies and leaves blow in the wind as you fight your way through 7 perilous worlds of Valkyries, Ninja, Dragons and even pesky fireflies waiting to feed on your carcass. Use your incredible acrobatic abilities to outsmart your enemies. Be brave... for ahead lies the Challenge of the Dragon!' FROM games WHERE igdb_id = 48294 ON CONFLICT (game_id, language_code) DO NOTHING;
