INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Magic Sword: Heroic Fantasy', 'Magic Sword fully titled as Magic Sword: Heroic Fantasy, is a side-scrolling fantasy arcade game released by Capcom in 1990. The game casts the player as a hero who must fight his way through a mystical tower in order to save the world. The player can use a sword, axe or magic, and can also rescue and recruit potential allies of various character classes, each of which has his or her own special abilities. Three years earlier, Capcom had released the similar Black Tiger in 1987.' FROM games WHERE igdb_id = 39500 ON CONFLICT (game_id, language_code) DO NOTHING;
