INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('spindizzy-worlds', 15374, '1990-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5zas.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sco5k5.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spindizzy Worlds', 'On it''s most basic level, Spindizzy Worlds is, like its predecessor, similar to Marble Madness. Controlling GERALD, you must move through the isometrically viewed landscape (largely flick-screen on the ST). There are two skill levels; the harder one features more of the precarious ledges and falls of Spindizzy. Each one takes you to a different matrix of levels, which can be played in different orders and each consist of 10 screens, with a bonus level at the end. You have limited energy, which can be recharged by collecting crystals. Fuel is limited, and is reduced by contact with hazards - generating a replacement GERALD takes time. There are many gates which are opened by running into spaces of the same colour. There are also aliens to avoid, and most movement is along thin slippery ledges with heavily inertia-based controls.' FROM games WHERE igdb_id = 15374 ON CONFLICT (game_id, language_code) DO NOTHING;
