INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cisco Heat', 'Cisco Heat is a racing game with a two-speed shifter and a chase view. Take on the role of an officer who must race his squad car through San Francisco in an attempt to win the first ever ''National Championship Police Car Steeplechase''. The roads have 90-degree turns, and it includes sights such as the famous trams and the Golden Gate Bridge. The player can pick from two police cars, one designed for power and another designed for handling.' FROM games WHERE igdb_id = 12005 ON CONFLICT (game_id, language_code) DO NOTHING;
