INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Torvak the Warrior', 'Torvak the Warrior is a hack and slash platform game. It was released for the Commodore Amiga and Atari ST. The gameplay has been compared to that of the Rastan Saga series. Armed with a double headed axe, you play the role of Torvak. Set out across the land of Ragnor with your mind set on a sole task - to avenge the evil Necromancer and bring peace back to your homeland. The game consists of five scrolling levels of increasing difficulty.' FROM games WHERE igdb_id = 12799 ON CONFLICT (game_id, language_code) DO NOTHING;
