INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Edd the Duck!', 'On childrens TV in the early 90s, Edd the Duck and Wilson the arm were the familiar puppets helping with the link sections. Like most child-oriented licenses of the day, his first computer outing was a platform game, scrolling vertically and resembling Rainbow Islands, although much simplified.' FROM games WHERE igdb_id = 79981 ON CONFLICT (game_id, language_code) DO NOTHING;
