INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Conflict', 'Conflict is a hex-based NES war game where the player is a three-star general who must accompany his troops to the ultimate victory. The player can earn or lose victory points by occupying cities and destroying units of the opponent''s army. The player controls the Western Bloc while the computer (or second player) controls Eastern Bloc troops. A sequel was released for the Super NES entitled Super Conflict.' FROM games WHERE igdb_id = 48143 ON CONFLICT (game_id, language_code) DO NOTHING;
