INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World Soccer Finals', 'World Soccer Finals is a Coin-Operated Arcade Video Game produced by Leland in 1990.  This game ranks a 1 on a scale out of 100 (100 = most often seen, 1=least common) in popularity based on census ownership records.  Other machines made by Leland during the time period World Soccer Finals was produced include Pig Out, Ataxx, Brute Force, Danny Sullivan''s Indy Heat, Dragon''s Lair II, Ironman Ivan Stewart''s Super Off Road, Ironman Ivan Stewart''s Super Off Road Track Pak, All American Football, Viper, and Strike Zone Baseball.' FROM games WHERE igdb_id = 38560 ON CONFLICT (game_id, language_code) DO NOTHING;
