INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dirty-harry', 3142, '1990-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5ah5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/s7bqrbvl1dti188n54xb.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dirty Harry', 'Dirty Harry is based on the popular Clint Eastwood movie character of "Dirty" Harry Callahan (rather than the specific movie "Dirty Harry"), a cop famous for his use of a .44 magnum for doing away with evildoers, and for his catchphrase, "Go ahead, make my day." In fact, the game begins with a digitized sample of that quote. The game play consists primarily of side-scrolling action. Dirty Harry can punch and kick the copious thugs that assault him using their own fists, guns, baseball bats, nets, and dynamite. The hero can also pull is .44 and aim it in 5 directions in order to pick off enemies, but the ammo is limited. Further, Dirty Harry has a number of other tools at his disposal, provided he collects them.' FROM games WHERE igdb_id = 3142 ON CONFLICT (game_id, language_code) DO NOTHING;
