INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Paradroid 90', 'Paradroid 90 is a remake of the game Paradroid (released in 1985 for the Commodore 64) for slightly later systems. A fleet of space freighters carry a cargo of battle and security robots to help in the defence of Basmyth. Alien ships were bombarding the freighters with disorienting beams which drove the robots crazy. The human officers were eliminated, leaving the ships open for occupation by alien forces. At this point the players mission starts...' FROM games WHERE igdb_id = 13253 ON CONFLICT (game_id, language_code) DO NOTHING;
