INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fossil Hunter', 'Fossil Hunter is an educational game for the Apple II. The player takes on the role of a fossil hunter, and has the opportunity to dig in a variety of rock layers to identify the contained fossilized animals. The player can learn more about the animal groups with a small encyclopedia included with the game.' FROM games WHERE igdb_id = 152024 ON CONFLICT (game_id, language_code) DO NOTHING;
