INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('motor-psycho', 28529, '1990-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co31zx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar8v4.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Motor Psycho', 'You finished it at last! And now you are going crazy waiting to test your sleek, hot, fast customized bike. It absorbs your every waking moment, you dream about it every night. It has become an obsession. And you know just the place to try it out. The annual MotorPsycho Competition (for deranged, psychopathic, and other unusual biker types) is this weekend! Its obstacle-laden course is legendary among motorcycle maniacs. Of course, nobody in their right mind would attempt this course. The die-hard spectators remind you that fan is short for fanatic. They''ve staked out their favorite spots to view the races, and they are waiting for the roar of revving engines, the squeal of tires, the crunch of metal... It''s you against the clock and your bike is built for speed. All you need to do is point it in the right direction and go for it! Four different tracks will separate the veterans from the rookies. (Or the schizophrenics from the psychotics.) Weekend amateurs will eat your dust, but you''ve got some pretty insane competition from your fellow, uh, pros. Some of these guys look hungry for the sweet taste of victory, but some of them look hungry for the taste of raw meat! So rev ''er up and let ''er rip! The winner''s circle (or the guy with the clean white coat) awaits.' FROM games WHERE igdb_id = 28529 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 28529 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;
