INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('guardian-ii-revenge-of-the-mutants', 152477, '1990-04-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3a6n.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scaifh.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Guardian II: Revenge of the Mutants', 'The mutants are back and this time they''re faster. In your Mk.II Fighter you have to stop the Raiders flying across the planet and picking up Earthlings and turning them to Mutants when they reach the top of the screen. When all Earthlings are gone then it''s game over. If you shoot a Raider holding an Earthling then it will drop him. You have to catch the Earthling and place him back on the surface. Other aliens to worry about are Hive, Dynamo, Technofighter, Firebomber and Lure. To help you in your fight you have a long range scanner, smart bomb, energy cloak, Hive convergence indicator and hyperfate. Guardian II is a Defender style 1 or 2 player horizontally sidewards scrolling shoot-em-up where you can go left or right. The joystick is used to steer your ship while the fire button fires your weapon. As well as your main playing area you can also see your radar, score and lives.' FROM games WHERE igdb_id = 152477 ON CONFLICT (game_id, language_code) DO NOTHING;
