INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Magical Dinosaur Tour', 'You''re exploring a primeval forest over 100 million years ago. Suddenly, the mighty Tyrannosaurus appears! With a push of a button, you bring him to life! The magic of TurboGrafx-CD brings the exciting world of dinosaurs into your home. Move through 20 prehistoric panoramas and watch creatures spring into action as they search for food and struggle for survival. Sort through hundreds of the mighty beasts and see what may have led to their ultimate extinction.' FROM games WHERE igdb_id = 42014 ON CONFLICT (game_id, language_code) DO NOTHING;
