INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nantettatte!! Baseball', 'A baseball game by Sunsoft released on the Family Computer in 1991. Nantettatte!! Baseball is a baseball game with the innovative feature of being able to update team rosters without needing to buy a brand new full price game. This is done by inserting a mini-cartridge that updates the roster into the main game.' FROM games WHERE igdb_id = 48811 ON CONFLICT (game_id, language_code) DO NOTHING;
