INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kid-gloves', 12656, '1990-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co99ec.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/pwhkoqg4lfhzvaoihf84.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kid Gloves', 'Although not released for 8-bit systems, this platform game has a definite Commodore 64 feel to it. Bright primary colours and smiling characters are used to tell the tale of Kid''s journey to rescue his girlfriend. The levels feature an assortment of enemies to kill, including snakes, elves and crocodiles, as well as flames and spinning wheels. Many of these appear during the level, forcing you to plan for them. You have 10 lives, but the loss of one resets the level to its original state. The initial coin-throwing is pretty weedy, but better weapons (as well as extra lives and smart bombs) can be bought in the shop, which appears every 5 screens. The levels are flick-screen, and can usually be finished in different ways, which results in different starting positions on the next screen, and you can travel back and forth through them, for example to pick up bonuses which are visible but not accessible as the level starts.' FROM games WHERE igdb_id = 12656 ON CONFLICT (game_id, language_code) DO NOTHING;
