INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('psychosis', 42099, '1990-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4bah.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/uqxrllg0fw490svwpfwv.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Psychosis', 'This is a side-scrolling shooter played in a world created from the mind of a twisted demon. Your soul has suddenly wandered into that evil world that exists in every person''s heart. The only way out is to blast your way past the grotesque creatures that block your path in five "causes" (stages). You must face the dangers of this psychedelic world by making full use of three shot types and the satellite option. With power-ups, you can change your shots to a wide-coverage beam, a satellite-generated laser and more. Each shot type can be powered up to three levels. You can also block enemy fire by rotating the satellites to a desired position. How you use these features will be the key to successfully escaping this strange and surreal world' FROM games WHERE igdb_id = 42099 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 42099 AND c.slug = 'nec' ON CONFLICT DO NOTHING;
